INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CongDon1207/AGENTS.md/angular-api-service', 'angular-api-service', 'CongDon1207', 'AGENTS.md', 'community', 'angular-api-service CongDon1207 AGENTS.md community Angular API服务AI智能代理，帮助开发者快速复制和粘贴代码，简化开发流程 Angular APIサービスは、開発者がコードを簡単にコピーして貼り付けることができるAIエージェントです Angular API 서비스는 개발자가 코드를 쉽게 복사하고貼付할 수 있는 AI 에이전트입니다 angular-api-service es un servicio de API para Angular que te permite copiar y pegar la carpeta para empezar a trabajar angular-api-service est un service d''API pour Angular qui vous permet de copier et coller le dossier pour commencer à travailler angular-api-service ist ein API-Service für Angular, mit dem Sie die Mappe kopieren und einfügen können, um zu beginnen O serviço de API Angular é uma ferramenta de IA que ajuda a copiar e colar a pasta e o arquivo AGENTS.md para o diretório raiz do seu projeto Сервис Angular API - это инструмент ИИ, который помогает копировать и вставлять папку и файл AGENTS.md в корень вашего проекта خدمة واجهة برمجة تطبيقات أنجولار هي أداة ذكاء اصطناعي تساعد في نسخ ولصق المجلد والملف AGENTS.md إلى 根 目录 مشروعك Copy .* folder and AGENTS.md then paste /root of project Angular API服务 AI智能代理 代码复制和粘贴 开发效率 Angular开发 AI工具 代码自动化 开发流程简化 Copy .* folder and AGENTS.md then paste /root of project ');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('asnar00/miso/android-stop-app', 'community', 'asnar00', 'miso', 'asnar00/miso', 'android-stop-app', 0, 0, 52, '2026-03-04T13:07:01.689Z', '2026-03-04T13:30:57.278Z', 'ea93e1e3c633a41040ad201ffe50f443575839e2474826a6d83d9e3a1dab19bb', '{"id":"asnar00/miso/android-stop-app","name":"android-stop-app","description":{"zh":"Android 应用停止工具可以帮助您停止后台运行的应用，优化系统性能。通过 AIエージェント 实现智能化的应用管理","ja":"Android アプリ停止ツールは、バックグラウンドで実行されているアプリを停止し、システムのパフォーマンスを最適化します。AIエージェントを使用して、アプリの管理をスマート化します","ko":"안드로이드 앱停止 도구는 백그라운드에서 실행 중인 앱을停止하여 시스템 성능을 최적화합니다. AI 에이전트를 사용하여 앱 관리를智能化하세요","es":"El agente ''android-stop-app'' permite detener aplicaciones Android de manera remota. Aprenda a utilizarlo para mejorar su desarrollo de aplicaciones móviles.","fr":"L''agent ''android-stop-app'' permet d''arrêter les applications Android à distance. Découvrez comment l''utiliser pour améliorer votre développement d''applications mobiles.","de":"Der Agent ''android-stop-app'' ermöglicht es, Android-Apps remote zu beenden. Erfahren Sie, wie Sie ihn nutzen können, um Ihre mobile App-Entwicklung zu verbessern.","pt":"A habilidade android-stop-app permite parar aplicativos Android de forma eficiente. Aprenda a utilizá-la para melhorar a produtividade.","ru":"Возможность android-stop-app позволяет остановить приложения Android эффективно. Узнайте, как использовать ее для повышения производительности.","ar":"القدرة على إيقاف تطبيقات الأندرويد تسمح بإيقاف تطبيقات الأندرويد بفعالية. تعلم كيفية استخدامها لتحسين الإنتاجية.","en":"make it so"},"seo":{"title":{"zh":"Android 应用停止工具 - AIエージェント","ja":"Android アプリ停止ツール - AIエージェント","ko":"안드로이드 앱停止 도구 - AI 에이전트","es":"Detener Aplicaciones Android con Agentes de IA","fr":"Arrêter les Applications Android avec des Outils d''IA","de":"Beenden Sie Android-Apps mit KI-Agents","pt":"Ferramentas de IA: Parar Aplicativos An