INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pydantic/monty/python-playground', 'python-playground', 'pydantic', 'monty', 'community', 'python-playground pydantic monty community python-playground是一个使用Rust编写的minimal和secure的Python解释器，用于AI应用 python-playgroundは、AIアプリケーション用にRustで書かれた最小限且安全なPythonインタープリターです python-playground는 AI 애플리케이션용으로 Rust로 작성된 최소한으로 안전한 파이썬 인터프리터입니다 El entorno de Python para Agentes de IA es un intérprete minimalista y seguro escrito en Rust L''environnement Python pour Outils d''IA est un interpréteur minimaliste et sécurisé écrit en Rust Die Python-Umgebung für KI-Agents ist ein minimalistischer und sicherer Interpreter, geschrieben in Rust O python-playground é um interpretador Python mínimo e seguro escrito em Rust para uso em IA Python-playground - это минималистичный и безопасный интерпретатор Python, написанный на Rust для ИИ python-playground هو محرك بايثون آمن ومحدود للغاية مكتوب بلغة روست للاستخدام في الذكاء الاصطناعي A minimal, secure Python interpreter written in Rust for use by AI python-playground AI工具 Python解释器 Rust编写 如何使用python-playground python-playground安装 python-playground教程 A minimal, secure Python interpreter written in Rust for use by AI');
