INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Vulnetix/vdb-api/commit-feature', 'commit-feature', 'Vulnetix', 'vdb-api', 'community', 'commit-feature Vulnetix vdb-api community commit-feature VDB API是为外部用户提供的AI工具，用于简化开发流程 commit-feature VDB APIは、外部ユーザー向けのAIエージェントで、開発プロセスを簡素化します commit-feature VDB API는 외부 사용자를 위한 AI 에이전트로 개발 프로세스를 단순화합니다 commit-feature es una API de base de datos vectoriales (VDB) diseñada para desarrolladores externos. Permite integrar capacidades de búsqueda semántica y gestión de embeddings en aplicaciones usando Python, Node.js o herramientas CLI. commit-feature est une API de base de données vectorielles (VDB) conçue pour les utilisateurs externes. Elle permet d''intégrer la recherche sémantique et la gestion d''embeddings dans des applications avec Python, Node.js ou des outils CLI. commit-feature ist eine Vector Database (VDB) API für externe Nutzer. Sie ermöglicht die Integration semantischer Suche und Embedding-Verwaltung in Anwendungen mit Python, Node.js oder CLI-Tools. O commit-feature é uma ferramenta de IA que utiliza a VDB API para melhorar a colaboração entre desenvolvedores ИИ Агент commit-feature использует VDB API для улучшения сотрудничества между разработчиками أداة الذكاء الاصطناعي commit-feature تستخدم VDB API لتحسين التعاون بين المطورين VDB API for external users 如何使用commit-feature VDB API 什么是commit-feature commit-feature VDB API安装 commit-feature VDB API设置指南 commit-feature VDB API替代品 commit-feature VDB API与其他工具的比较 VDB API for external users');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('davidmoneil/AIfred/project-lifecycle', 'community', 'davidmoneil', 'AIfred', 'davidmoneil/AIfred', 'project-lifecycle', 0, 0, 52, '2026-03-04T13:07:01.770Z', '2026-03-04T14:20:22.049Z', '86e16d8047d9a29478b0c588228d5fae3dfaab2a67aefceedc8d21c104009fde', '{"id":"davidmoneil/AIfred/project-lifecycle","name":"project-lifecycle","description":{"zh":"AIfred 是一个 AI 启用的命令控制台，用于管理 homelab 服务、监控和日志，解决常见问题","ja":"AIfred はホームラボのサービス、監視、ログを管理する AI エージェントコマンドデッキです","ko":"AIfred는 홈랩 서비스를 관리하고 모니터링하고 로그를 분석하여 일반적인 문제를 해결하는 AI 에이전트 명령 콘솔입니다","es":"AIfred es una herramienta de agente de inteligencia artificial que gestiona el ciclo de vida del proyecto, explicando problemas en un lenguaje sencillo","fr":"AIfred est un outil d''agent d''intelligence artificielle qui gère le cycle de vie du projet, expliquant les problèmes dans un langage simple","de":"AIfred ist ein KI-Agents-Tool, das den Projekt-Lebenszyklus verwaltet und Probleme in einfacher Sprache erklärt","pt":"AIfred é uma plataforma de comando habilitada para IA que inventaria serviços, monitora uptime e logs, explica problemas em linguagem simples e executa runbooks para resolver problemas comuns","ru":"AIfred — это платформа командного управления, оснащенная ИИ, которая инвентаризирует сервисы, мониторит uptime и логи, объясняет проблемы на простом языке и выполняет runbooks для решения общих проблем","ar":"AIfred هي منصة لوحة تحكم مدعومة بالذكاء الاصطناعي التي تجري جردًا للخدمات وتراقب الوقت التشغيلي والسجلات وتصف المشكلات باللغة البسيطة وتنفذ الكتب التشغيلية لحل المشكلات الشائعة","en":"AIfred is an AI-enabled command deck for your homelab: it inventories services, watches uptime and logs, explains issues in plain English, and can safely execute runbooks to fix common problems."},"seo":{"title":{"zh":"AI智能代理项目生命周期管理","ja":"AIエージェントによるプロジェクトライフサイクル管理","ko":"AI 에이전트 프로젝트 라이프사이클 관리","es":"Herramientas de Agente de Inteligencia Artificial para Ci...","fr":"Outils d''Agents d''Intelligence Artificielle pour Cycle de...","de":"KI-Agents-Tools für Projekt-Lebenszyklus","pt":"Ferramentas de Agente de IA para Ciclo de Vida do Projeto","ru":"ИИ Агенты для Жизненного Цикла Проекта","ar":"أدوات وكلاء الذكاء الاصطناعي لمراحل دورة الحياة","en":"project-lifecycle"},"description":{"zh":"AIfred 是一个 AI 启用的命令控制台，用于管理 homelab 服务、监控和日志，解决常见问题","ja":"AIfred はホームラボのサービス、監視、ログを管理する AI エージェントコマンドデッキです","ko":"AIfred는 홈랩 서비스를 관리하고 모니터링하고 로그를 분석하여 일반적인 문제를 해결하는 AI 에이전트 명령 콘솔입니다","es":"AIfred es una herramienta de agente de inteligencia artificial que gestiona el ciclo de vida del proyecto, explicando problemas en un lenguaje sencillo","fr":"AIfred est un outil d''agent d''intelligence artificielle qui gère le cycle de vie du projet, expliquant les problèmes dans un langage simple","de":"AIfred ist ein KI-Agents-Tool, das den Projekt-Lebenszyklus verwaltet und Probleme in einfacher Sprache erklärt","pt":"AIfred é uma plataforma de comando habilitada para IA que inventaria serviços, monitora uptime e logs, explica problemas em linguagem simples e executa runbo...","ru":"AIfred — это платформа командного управления, оснащенная ИИ, которая инвентаризирует сервисы, мониторит uptime и логи, объясняет проблемы на простом языке и ...","ar":"AIfred هي منصة لوحة تحكم مدعومة بالذكاء الاصطناعي التي تجري جردًا للخدمات وتراقب الوقت التشغيلي والسجلات وتصف المشكلات باللغة البسيطة وتنفذ الكتب التشغيلية ل...","en":"AIfred is an AI-enabled command deck for your homelab: it inventories services, watches uptime and logs, explains issues in plain English, and can safely exe..."},"definition":{"en":"AIfred is an AI-enabled command deck for your homelab: it inventories services, watches uptime and logs, explains issues in plain English, and can safely execute runbooks to fix common problems."},"features":{"zh":["服务管理","监控和日志分析","问题解决","安全运行书","命令控制台"],"ja":["サービス管理","監視とログ分析","問題解決","安全なランブック","コマンドデッキ"],"ko":["서비스 관리","모니터링 및 로그 분석","문제 해결","안전한 런북","명령 콘솔"],"es":["Inventario de servicios","Supervisión de tiempo de actividad y registros","Explicación de problemas en lenguaje sencillo","Ejecución segura de runbooks","Gestión del ciclo de vida del proyecto"],"fr":["Inventaire des services","Surveillance du temps d''activité et des journaux","Explication des problèmes dans un langage simple","Exécution sécurisée de runbooks","Gestion du cycle de vie du projet"],"de":["Inventarisierung von Diensten","Überwachung von Betriebszeit und Protokollen","Erklärung von Problemen in einfacher Sprache","Sichere Ausführung von Runbooks","Verwaltung des Projekt-Lebenszyklus"],"pt":["Inventário de serviços","Monitoramento de uptime e logs","Explicação de problemas em linguagem simples","Execução de runbooks para resolver problemas comuns","Gerenciamento do ciclo de vida do projeto com IA"],"ru":["Инвентаризация сервисов","Мониторинг uptime и логов","Объяснение проблем на простом языке","Выполнение runbooks для решения общих проблем","Управление жизненным циклом проекта с помощью ИИ"],"ar":["جرد الخدمات","مراقبة الوقت التشغيلي والسجلات","توضيح المشكلات باللغة البسيطة","تنفيذ الكتب التشغيلية لحل المشكلات الشائعة","إدارة دورة حياة المشروع بالذكاء الاصطناعي"]},"keywords":{"zh":["AI智能代理","项目生命周期管理","homelab管理","服务管理","监控和日志分析","问题解决","AIfred教程","AIfred安装","AIfred设置指南"],"ja":["AIエージェント","プロジェクトライフサイクル管理","ホームラボ管理","サービス管理","監視とログ分析","問題解決","AIfredチュートリアル","AIfredインストール","AIfred設定ガイド"],"ko":["AI 에이전트","프로젝트 라이프사이클 관리","홈랩 관리","서비스 관리","모니터링 및 로그 분석","문제 해결","AIfred 튜토리얼","AIfred 설치","AIfred 설정 가이드"],"es":["cómo usar herramientas de agente de inteligencia artificial","qué es un agente de inteligencia artificial","AIfred alternativa","AIfred vs otros agentes de inteligencia artificial","instalación de AIfred","guía de configuración de AIfred","herramientas de inteligencia artificial para proyectos","gestión de proyectos con inteligencia artificial"],"fr":["comment utiliser des outils d''agents d''intelligence artificielle","qu''est-ce qu''un agent d''intelligence artificielle","AIfred alternative","AIfred vs d''autres agents d''intelligence artificielle","installation d''AIfred","guide de configuration d''AIfred","outils d''intelligence artificielle pour les projets","gestion de projets avec intelligence artificielle"],"de":["wie man KI-Agents-Tools verwendet","was ist ein KI-Agent","AIfred-Alternative","AIfred vs andere KI-Agents","Installation von AIfred","Einrichtungsanleitung für AIfred","KI-Tools für Projekte","Projektverwaltung mit KI"],"pt":["como usar agente de ia","o que é agente de ia","ferramentas de agente de ia","alternativas ao jira","guia de instalação do aifred","configuração do aifred","treinamento de agente de ia","certificação de agente de ia"],"ru":["как использовать ии агент","что такое ии агент","инструменты ии агента","альтернативы jira","руководство по установке aifred","настройка aifred","обучение ии агенту","сертификация ии агента"],"ar":["كيفية استخدام وكيل الذكاء الاصطناعي","ما هو وكيل الذكاء الاصطناعي","أدوات وكلاء الذكاء الاصطناعي","بديل جيرا","دليل تثبيت أيفريد","إعداد أيفريد","تدريب وكيل الذكاء الاصطناعي","شهادة وكيل الذكاء الاصطناعي"]}},"owner":"davidmoneil","repo":"AIfred","repoPath":"davidmoneil/AIfred","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.770Z","topics":[],"category":"community","skillMd":{"name":"project-lifecycle","description":"End-to-end project management from creation through consolidation and archival","version":"1.0.0","tags":["projects","lifecycle","creation","registration","consolidation"],"bodyPreview":"# Project Lifecycle Skill\n\nComplete project management workflow from creation through consolidation and archival.\n\n---\n\n## Overview\n\nThis skill consolidates all project lifecycle operations:\n- **Creation**: New code projects in ~/Code or internal projects in .claude/projects\n- **Registration**: Register existing projects with AIfred tracking\n- **Consolidation**: Sync knowledge, update docs, create commits\n- **Management**: Track priorities, update context files\n\n**Value**: Unified approach to pr","body":"# Project Lifecycle Skill\n\nComplete project management workflow from creation through consolidation and archival.\n\n---\n\n## Overview\n\nThis skill consolidates all project lifecycle operations:\n- **Creation**: New code projects in ~/Code or internal projects in .claude/projects\n- **Registration**: Register existing projects with AIfred tracking\n- **Consolidation**: Sync knowledge, update docs, create commits\n- **Management**: Track priorities, update context files\n\n**Value**: Unified approach to project management with consistent patterns and documentation.\n\n---\n\n## Quick Actions\n\n| Need | Action | Reference |\n|------|--------|---------|\n| Create new code project | `/new-code-project <name>` | @.claude/commands/new-code-project.md |\n| Register existing project | `/register-project <path-or-url>` | @.claude/commands/register-project.md |\n| Create internal project | `/create-project <name>` | @.claude/commands/create-project.md |\n| Consolidate project knowledge | `/consolidate-project <name>` | @.claude/commands/consolidate-project.md |\n\n---\n\n## Project Lifecycle Workflow\n\n```\nPROJECT LIFECYCLE\n=================\n\nCREATE (new projects)\n  /new-code-project <name>\n    - Creates in ~/Code/<name>\n    - Initializes git, README, .claude/CLAUDE.md\n    - Registers in paths-registry.yaml\n    - Creates context file at .claude/context/projects/<name>.md\n\n  /create-project <name>\n    - Creates internal project in .claude/projects/<name>\n    - For non-code projects (writing, research, planning)\n    - Creates project structure with config.yaml\n\nREGISTER (existing projects)\n  /register-project <path-or-url>\n    - Clones GitHub URL to ~/Code/ if needed\n    - Auto-detects language/type\n    - Adds to paths-registry.yaml\n    - Creates context file\n\nCONSOLIDATE (ongoing maintenance)\n  /consolidate-project <name>\n    - Updates context file with current state\n    - Syncs documentation with code\n    - Creates git commit with changes\n    - Options: --infrastructure, --analyze, --all\n\nARCHIVE (completed projects)\n  - Move context to .claude/context/archive/\n  - Update paths-registry.yaml status\n  - Optional: Remove from ~/Code/\n```\n\n---\n\n## Project Locations\n\nUnderstanding where projects live:\n\n| Project Type | Location | Registration |\n|--------------|----------|--------------|\n| Code projects | `~/Code/<project>/` | `paths-registry.yaml` → `coding.projects` |\n| Internal projects | `.claude/projects/<project>/` | Direct in AIfred |\n| Context/notes | `.claude/context/projects/<project>.md` | Always in AIfred |\n| External sources | `external-sources/<category>/` | Symlinks to external data |\n\n---\n\n## Context File Template\n\nWhen creating project context files, use this structure:\n\n```markdown\n# Project: <name>\n\n**Type**: web-app | api | cli | library | docker | internal\n**Language**: typescript | python | go | rust | N/A\n**Location**: ~/Code/<name> or .claude/projects/<name>\n**Status**: active | maintenance | archived\n**Created**: YYYY-MM-DD\n\n## Overview\n\nBrief description of project purpose.\n\n## Key Files\n\n- `src/` - Main source code\n- `README.md` - Project documentation\n\n## Current State\n\nWhat''s working, what''s in progress.\n\n## Integration Points\n\nHow this connects to AIfred infrastructure.\n```\n\n---\n\n## Registration Patterns\n\n### GitHub URL Detection\n\nWhen user mentions a GitHub URL:\n1. Check if already registered in `paths-registry.yaml`\n2. If not, clone to `~/Code/<repo-name>`\n3. Auto-detect language from file extensions\n4. Add to registry under `coding.projects`\n5. Create context file\n\n### Existing Local Project\n\nWhen registering an existing local project:\n1. Verify path exists\n2. Detect project type and language\n3. Add to `paths-registry.yaml`\n4. Create context file\n5. Optionally initialize `.claude/CLAUDE.md` in project\n\n---\n\n## Integration Points\n\n### With Session Management\n- New projects can be noted in session-state.md\n- Project work tracked via current-priorities.md\n\n### With Orchestration\n- Complex project setup may trigger orchestration\n- Use `/orchestration:plan \"setup [project]\"` for multi-phase setup\n\n### With Memory MCP\n- Store project metadata as Memory entities\n- Track project relationships and dependencies\n\n### With paths-registry.yaml\n- Source of truth for all project locations\n- Check before assuming any path\n\n---\n\n## Common Workflows\n\n### Starting a New Feature Project\n\n```\n1. /new-code-project my-feature --type api --lang typescript\n2. Review generated structure in ~/Code/my-feature\n3. Update context file with specific requirements\n4. Begin development\n```\n\n### Onboarding Existing Project\n\n```\n1. /register-project https://github.com/user/repo\n2. Review auto-detected settings\n3. Update context file with domain knowledge\n4. Add any custom CLAUDE.md to the project\n```\n\n### Project Knowledge Sync\n\n```\n1. /consolidate-project my-project\n2. Review documentation updates\n3. Commit changes\n4. Update session-state.md if needed\n```\n\n---\n\n## Troubleshooting\n\n### Project not appearing in registry?\n- Check `paths-registry.yaml` directly\n- Verify path exists: `ls ~/Code/<project>`\n- Re-run `/register-project <path>`\n\n### Context file out of date?\n- Run `/consolidate-project <name>`\n- Review changes before committing\n- Update manually if consolidation misses details\n\n### Git clone failing?\n- Check SSH key: `ssh -T git@github.com`\n- Verify URL format\n- Check network connectivity\n\n---\n\n## Related Documentation\n\n### Commands\n- @.claude/commands/new-code-project.md - New code project creation\n- @.claude/commands/register-project.md - Project registration\n- @.claude/commands/create-project.md - Internal project creation\n- @.claude/commands/consolidate-project.md - Project consolidation\n\n### Context Files\n- @paths-registry.yaml - Project registration source of truth\n- @.claude/context/projects/ - All project context files\n- @.claude/templates/project-template/ - Project template structure\n\n### Patterns\n- @.claude/context/patterns/memory-storage-pattern.md - When to store in Memory\n- @.claude/context/standards/documentation-location.md - Where to document\n"},"lastSynced":"2026-03-04T14:20:22.049Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude Code and AutoGPT needing comprehensive project management capabilities from creation to archival.","zh":"适用于 Claude Code 和 AutoGPT 等 AI Agent，需要从创建到存档的全面项目管理功能。","ja":"Claude Code や AutoGPT などの AI エージェントに適しています。プロジェクトの作成からアーカイブまでの包括的なプロジェクト管理機能が必要です。","ko":"Claude Code 및 AutoGPT와 같은 AI 에이전트에 적합합니다. 생성에서 보관까지 종합적인 프로젝트 관리 기능이 필요합니다.","es":"Ideal para agentes de IA como Claude Code y AutoGPT que necesitan capacidades de gestión de proyectos integrales desde la creación hasta el archivo.","fr":"Idéal pour les agents IA comme Claude Code et AutoGPT nécessitant des capacités de gestion de projets complètes de la création à l''archivage.","de":"Ideal für KI-Agents wie Claude Code und AutoGPT, die umfassende Projektmanagementfunktionen von der Erstellung bis zum Archiv benötigen.","pt":"Ideal para Agentes de IA como Claude Code e AutoGPT que necessitam de capacidades de gerenciamento de projetos abrangentes desde a criação até o arquivamento.","ru":"Идеально для агентов ИИ, таких как Claude Code и AutoGPT, которым необходимы комплексные возможности управления проектами от создания до архивации.","ar":"مثالي لوكلاء الذكاء الاصطناعي مثل Claude Code و AutoGPT الذين يحتاجون إلى قدرات إدارة مشاريع شاملة من الإنشاء إلى الأرشفة."},"recommendation":{"en":"Empowers agents to manage project lifecycles by consolidating creation, registration, consolidation, and management tasks, utilizing runbooks and tracking project priorities, all while updating context files and syncing knowledge.","zh":"使代理能够通过整合创建、注册、整合和管理任务来管理项目生命周期，利用 runbooks 跟踪项目优先级，同时更新上下文文件和同步知识。","ja":"エージェントは、runbooks を使用してプロジェクトの優先順位を追跡し、同時にコンテキストファイルを更新し、知識を同期することで、作成、登録、統合、管理タスクを統合してプロジェクトのライフサイクルを管理できます。","ko":"에이전트가 런북을 사용하여 프로젝트의 우선순위를 추적하고,同時に 컨텍스트 파일을 업데이트하고 지식을 동기화함으로써 생성, 등록, 통합, 관리 작업을 통합하여 프로젝트 생명주기를 관리할 수 있도록 합니다.","es":"Habilita a los agentes a gestionar los ciclos de vida de los proyectos consolidando la creación, el registro, la consolidación y las tareas de gestión, utilizando libros de ejecución y seguimiento de prioridades de proyectos, todo mientras actualiza archivos de contexto y sincroniza conocimientos.","fr":"Permet aux agents de gérer les cycles de vie des projets en consolidant la création, l''enregistrement, la consolidation et les tâches de gestion, en utilisant des livres de suivi et en suivant les priorités des projets, le tout en mettant à jour les fichiers de contexte et en synchronisant les connaissances.","de":"Ermöglicht es den Agents, Projektlebenszyklen zu verwalten, indem sie die Erstellung, Registrierung, Konsolidierung und Verwaltungsaufgaben konsolidieren, Runbooks verwenden und Projekt Prioritäten verfolgen, während sie Kontextdateien aktualisieren und Wissen synchronisieren.","pt":"Habilita os agentes a gerenciar ciclos de vida de projetos consolidando criação, registro, consolidação e tarefas de gerenciamento, utilizando runbooks e acompanhando prioridades de projeto, atualizando arquivos de contexto e sincronizando conhecimento.","ru":"Наделяет агентов возможностью управлять жизненным циклом проектов, консолидируя создание, регистрацию, консолидацию и задачи управления, используя runbooks и отслеживая приоритеты проекта, обновляя контекстные файлы и синхронизируя знания.","ar":"يتمكّن الوكلاء من إدارة دورة حياة المشروع عن طريق توحيد إنشاء التسجيل وتوحيد والمهام الإدارية، واستخدام الكتب التشغيلية وتتبع أولويات المشروع، مع تحديث ملفات السياق وتزامن المعرفة."},"useCases":{"en":["Automating project onboarding by registering existing projects with AIfred tracking","Consolidating project knowledge by syncing documentation and creating commits","Managing project priorities by tracking and updating context files"],"zh":["通过 AIfred 跟踪注册现有项目来自动化项目入门","通过同步文档和创建提交来整合项目知识","通过跟踪和更新上下文文件来管理项目优先级"],"ja":["AIfred のトラッキングで既存のプロジェクトを登録してプロジェクトのオンボーディングを自動化する","ドキュメントを同期しコミットを作成することでプロジェクトの知識を統合する","コンテキストファイルを追跡して更新することでプロジェクトの優先順位を管理する"],"ko":["AIfred 추적을 통해 기존 프로젝트를 등록하여 프로젝트 온보딩을 자동화합니다.","문서를 동기화하고 커밋을 생성하여 프로젝트 지식을 통합합니다.","컨텍스트 파일을 추적하고 업데이트하여 프로젝트 우선순위를 관리합니다."],"es":["Automatizar la integración de proyectos mediante el registro de proyectos existentes con el seguimiento de AIfred","Consolidar el conocimiento del proyecto sincronizando la documentación y creando confirmaciones","Gestionar las prioridades del proyecto mediante el seguimiento y la actualización de archivos de contexto"],"fr":["Automatiser l''intégration de projets en enregistrant les projets existants avec le suivi AIfred","Consolider les connaissances du projet en synchronisant la documentation et en créant des validations","Gérer les priorités des projets en suivant et en mettant à jour les fichiers de contexte"],"de":["Automatisieren der Projektintegration durch Registrierung bestehender Projekte mit AIfred-Verfolgung","Konsolidieren des Projektwissens durch Synchronisierung der Dokumentation und Erstellung von Commits","Verwalten der Projekt Prioritäten durch Verfolgen und Aktualisieren von Kontextdateien"],"pt":["Automatizar o processo de integração de projetos registrando projetos existentes com o acompanhamento do AIfred","Consolidar o conhecimento do projeto sincronizando a documentação e criando commits","Gerenciar prioridades de projeto acompanhando e atualizando arquivos de contexto"],"ru":["Автоматизировать процесс интеграции проектов, регистрируя существующие проекты с отслеживанием AIfred","Консолидировать знания проекта, синхронизируя документацию и создавая коммиты","Управлять приоритетами проекта, отслеживая и обновляя контекстные файлы"],"ar":["تأتمتة عملية إدراج المشروع عن طريق تسجيل المشاريع الحالية مع تتبع AIfred","توحيد معرفة المشروع بمزامنة الوثائق وإبداء التعديلات","إدارة أولويات المشروع من خلال تتبع ملفات السياق و تحديثها"]},"limitations":{"en":["Requires AIfred command deck integration","Limited to projects in ~/Code or .claude/projects directories"],"zh":["需要 AIfred 命令集成","仅限于 ~/Code 或 .claude/projects 目录中的项目"],"ja":["AIfred コマンドデッキの統合が必要"," ~/Code または .claude/projects ディレクトリ内のプロジェクトのみに限定"],"ko":["AIfred 명령 덱 통합이 필요합니다.","~/Code 또는 .claude/projects 디렉토리 내의 프로젝트만 허용"],"es":["Requiere integración con la cubierta de comandos de AIfred","Limitado a proyectos en los directorios ~/Code o .claude/projects"],"fr":["Nécessite une intégration avec le pont de commandes AIfred","Limité aux projets dans les répertoires ~/Code ou .claude/projects"],"de":["Benötigt Integration mit dem Befehlsdeck von AIfred","Begrenzt auf Projekte in den Verzeichnissen ~/Code oder .claude/projects"],"pt":["Requer integração com o convés de comando do AIfred","Limitado a projetos nos diretórios ~/Code ou .claude/projects"],"ru":["Требует интеграции с командным деком AIfred","Ограничен проектами в директориях ~/Code или .claude/projects"],"ar":["يتطلب تكاملًا مع سطح التحكم في الأوامر AIfred","محدود بمشاريع في الدلائل ~/Code أو .claude/projects"]},"version":3},"contentHash":"86e16d8047d9a29478b0c588228d5fae3dfaab2a67aefceedc8d21c104009fde","qualityScore":52}');
