INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('niznik-dev/cruijff_kit/analyze-experiment', 'analyze-experiment', 'niznik-dev', 'cruijff_kit', 'community', 'analyze-experiment niznik-dev cruijff_kit community analyze-experiment工具提供了使用LLMs进行社会研究的功能，支持数据分析和实验设计 analyze-experimentツールはLLMsを使用した社会研究をサポートし、データ分析と実験設計が可能 analyze-experiment 도구는 LLMs를 사용한 사회 연구를 지원하며 데이터 분석과 실험 설계가 가능 La habilidad analyze-experiment ofrece herramientas para la investigación social con LLMs. Ayuda a los desarrolladores a mejorar sus proyectos con Agentes de IA La compétence analyze-experiment propose des outils pour la recherche sociale avec LLMs. Aide les développeurs à améliorer leurs projets avec Agents IA Die Fähigkeit analyze-experiment bietet Tools für die soziale Forschung mit LLMs. Hilft Entwicklern, ihre Projekte mit KI-Agenten zu verbessern As ferramentas de análise de experimentos com LLMs permitem que os desenvolvedores conduzam pesquisas sociais de forma eficaz ИИ Агенты для анализа экспериментов с LLMs позволяют разработчикам проводить социальные исследования эффективно أدوات تحليل التجارب مع LLMs تمكن المطورين من إجراء بحوث اجتماعية بفعالية Tools for conducting social research with LLMs 如何使用analyze-experiment工具 什么是LLMs analyze-experiment工具替代品 analyze-experiment工具与竞争对手比较 analyze-experiment工具安装 analyze-experiment工具设置指南 使用React和Python进行社会研究 LLMs在社会研究中的应用 Tools for conducting social research with LLMs');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jaydee829/agentic_librarian/project-memory', 'community', 'jaydee829', 'agentic_librarian', 'jaydee829/agentic_librarian', 'project-memory', 0, 0, 52, '2026-03-04T13:07:01.913Z', '2026-03-04T15:02:18.954Z', '8e57092a9ba4fb581864fe5b4644eb42806660783baa8c278cc95941494e7d9e', '{"id":"jaydee829/agentic_librarian/project-memory","name":"project-memory","description":{"zh":"project-memory是一个基于AI的智能书籍推荐系统，使用React和Python等技术","ja":"project-memoryは、AIエージェントを使用した本のレコメンドシステムで、ReactとPythonなどの技術を使用しています","ko":"project-memory는 AI 에이전트를 활용한 도서 추천 시스템으로, React와 Python 등의 기술을 사용합니다","es":"Project-memory es un sistema de recomendación de libros agente que utiliza inteligencia artificial para sugerir lecturas personalizadas a los usuarios","fr":"Project-memory est un système de recommandation de livres basé sur l''intelligence artificielle qui suggère des lectures personnalisées aux utilisateurs","de":"Project-memory ist ein empfehlungssystem für bücher, das künstliche intelligenz nutzt, um personalisierte leseempfehlungen an die benutzer zu geben","pt":"O project-memory é um sistema de recomendação de livros baseado em IA, projetado para ajudar os desenvolvedores a encontrar novos títulos.","ru":"Project-memory - это система рекомендации книг на основе ИИ, предназначенная для помощи разработчикам в поиске новых названий.","ar":"project-memory هو نظام توصية الكتب بالذكاء الاصطناعي، مصمم لمساعدة المطورين على العثور على عناوين جديدة.","en":"An agentic book recommender system"},"seo":{"title":{"zh":"AI智能书籍推荐系统 - project-memory","ja":"AIエージェントによる本のレコメンドシステム - project-memory","ko":"AI 에이전트를 활용한 도서 추천 시스템 - project-memory","es":"Herramientas de AI: project-memory, sistema de recomendac...","fr":"Outils IA: project-memory, système de recommandation de l...","de":"KI-Tools: project-memory, empfehlungssystem für bücher","pt":"Ferrame