INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('claudeaceae/samara-main/sync', 'sync', 'claudeaceae', 'samara-main', 'community', 'sync claudeaceae samara-main community sync技能为Claude提供持久的身体、记忆和代理，实现Mac上的AI智能体开发。使用Bootstrap规范，开发者可以轻松创建AI智能体 sync機能はClaudeに持続的なボディ、メモリ、エージェントを提供し、MacでのAIエージェント開発を実現します。Bootstrap仕様を使用して、開発者は簡単にAIエージェントを作成できます sync 기능은 클라우드에게 지속적인 몸, 기억, 에이전트를 제공하여 맥에서 AI 에이전트 개발을 구현합니다. 부트스트랩 사양을 사용하여 개발자는 쉽게 AI 에이전트를 만들 수 있습니다 Sync es una especificación de arranque para dar a Claude un cuerpo y memoria persistentes en Mac, permitiendo una mayor agencia y funcionalidad Sync est une spécification de démarrage pour donner à Claude un corps et une mémoire persistants sur Mac, permettant une plus grande agence et fonctionnalité Sync ist eine Boot-Spezifikation, um Claude einen persistenten Körper und Speicher auf Mac zu geben, wodurch eine größere Agentur und Funktionalität ermöglicht wird A habilidade de sincronização para Claude habilita uma presença persistente em Macs com especificação Bootstrap Возможность синхронизации для Claude обеспечивает постоянное присутствие на Mac с помощью спецификации Bootstrap مهارة التزامن ل Claude تمكن من وجود مستمر على أجهزة Mac باستخدام مواصفات Bootstrap Bootstrap specification for giving Claude a persistent body, memory, and agency on a Mac AI智能体 sync技能 Bootstrap规范 Mac开发 AI开发工具 如何使用sync技能 sync技能教程 AI智能体开发框架 Bootstrap specification for giving Claude a persistent body, memory, and agency on a Mac');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('agairola/securing-ralph-loop/self-check', 'community', 'agairola', 'securing-ralph-loop', 'agairola/securing-ralph-loop', 'self-check', 4, 0, 51, '2026-02-09T08:27:39Z', '2026-02-27T01:56:12.825Z', '5419b3c4096f82b15c8468403629089ebf07c64d1516daa4efc86b809d054ebd', '{"id":"agairola/securing-ralph-loop/self-check","name":"self-check","description":{"zh":"Ralph Loop自检AI智能代理是一种安全检查工具，用于扫描代码、迭代修复和升级安全问题","ja":"Ralph LoopセルフチェックAIエージェントは、コードをスキャンし、修復し、セキュリティ問題をエスカレートするセキュリティチェックツールです","ko":"랄프 루프 자기 검사 AI 에이전트는 코드를 스캔하고, 반복적으로 수정하고, 보안 문제를升级하는 보안 점검 도구입니다","es":"Self-Check es una herramienta de seguridad para Ralph Loop que realiza comprobaciones antes de commit. Ayuda a escanear, corregir y escalada cuando sea necesario.","fr":"Self-Check est un outil de sécurité pour Ralph Loop qui effectue des vérifications avant commit. Il aide à analyser, corriger et escalader au besoin.","de":"Self-Check ist ein Sicherheitstool für Ralph Loop, das Prüfungen vor dem Commit durchführt. Es hilft bei der Überprüfung, Korrektur und Eskalation bei Bedarf.","pt":"O self-check é uma ferramenta de segurança para o Ralph Loop, que realiza verificações de segurança antes do commit e corrige problemas iterativamente","ru":"Самопроверка - это инструмент безопасности для Ralph Loop, который выполняет проверки безопасности перед коммитом и исправляет проблемы итеративно","ar":"فحص ذاتي هو أداة أمنية لRALPH Loop، التي تقوم بفحوصات أمنية قبل الإلتزام وتصحيح المشاكل بشكل متكرر","en":"Security checks for the Ralph Loop - scan before commit, fix iteratively, escalate when stuck"},"seo":{"title":{"zh":"AI智能代理 - Ralph Loop自检安全检查","ja":"AIエージェント - Ralph Loopセルフチェックのセキュリティチェック","ko":"AI 에이전트 - 랄프 루프 자기 검사 보안 점검","es":"Herramientas de AI: Self-Check para Ralph Loop","fr":"Outils d''IA: Self-Check pour Ralph Loop","de":"KI-Tools: Self-Check für Ralph Loop","pt":"Ferramentas de IA: Self-Check para Ralph Loop","ru":"ИИ Агенты: Самопроверка для Ralph Loop","ar":"أدوات الذكاء الاصطناعي: فحص ذاتي لRALPH Loop","en":"self-check"},"description":{"zh":"Ralph Loop自检AI智能代理是一种安全检查工具，用于扫描代码、迭代修复和升级安全问题","ja":"Ralph LoopセルフチェックAIエージェントは、コードをスキャンし、修復し、セキュリティ問題をエスカレートするセキュリティチェックツールです","ko":"랄프 루프 자기 검사 AI 에이전트는 코드를 스캔하고, 반복적으로 수정하고, 보안 문제를升级하는 보안 점검 도구입니다","es":"Self-Check es una herramienta de seguridad para Ralph Loop que realiza comprobaciones antes de commit. Ayuda a escanear, corregir y escalada cuando sea neces...","fr":"Self-Check est un outil de sécurité pour Ralph Loop qui effectue des vérifications avant commit. Il aide à analyser, corriger et escalader au besoin.","de":"Self-Check ist ein Sicherheitstool für Ralph Loop, das Prüfungen vor dem Commit durchführt. Es hilft bei der Überprüfung, Korrektur und Eskalation bei Bedarf.","pt":"O self-check é uma ferramenta de segurança para o Ralph Loop, que realiza verificações de segurança antes do commit e corrige problemas iterativamente","ru":"Самопроверка - это инструмент безопасности для Ralph Loop, который выполняет проверки безопасности перед коммитом и исправляет проблемы итеративно","ar":"فحص ذاتي هو أداة أمنية لRALPH Loop، التي تقوم بفحوصات أمنية قبل الإلتزام وتصحيح المشاكل بشكل متكرر","en":"Security checks for the Ralph Loop - scan before commit, fix iteratively, escalate when stuck"},"definition":{"en":"Security checks for the Ralph Loop - scan before commit, fix iteratively, escalate when stuck"},"features":{"zh":["代码扫描","迭代修复","安全问题升级","Ralph Loop集成","CLI支持","Node.js兼容"],"ja":["コードスキャン","修復の反復","セキュリティ問題のエスカレート","Ralph Loopとの統合","CLIサポート","Node.jsとの互換性"],"ko":["코드 스캔","반복적인 수정","보안 문제升级","랄프 루프 통합","CLI 지원","Node.js 호환"],"es":["Comprobaciones de seguridad antes de commit","Escaneo y corrección de errores","Escalada cuando sea necesario","Integración con Ralph Loop","Análisis de vulnerabilidades"],"fr":["Vérifications de sécurité avant commit","Analyse et correction d''erreurs","Escalade au besoin","Intégration avec Ralph Loop","Analyse de vulnérabilités"],"de":["Sicherheitsprüfungen vor dem Commit","Überprüfung und Korrektur von Fehlern","Eskalation bei Bedarf","Integration mit Ralph Loop","Analyse von Schwachstellen"],"pt":["Verificações de segurança antes do commit","Correção de problemas iterativamente","Escalada de problemas quando necessário","Integração com o Ralph Loop","Melhoria da segurança do código"],"ru":["Проверки безопасности перед коммитом","Исправление проблем итеративно","Эскалация проблем при необходимости","Интеграция с Ralph Loop","Улучшение безопасности кода"],"ar":["فحوصات أمنية قبل الإلتزام","تصحيح المشاكل بشكل متكرر","توسيع المشاكل عند الحاجة","التكامل مع RALPH Loop","تحسين أمن الكود"]},"keywords":{"zh":["AI智能代理","Ralph Loop自检","安全检查工具","代码扫描","迭代修复","安全问题升级","如何使用Ralph Loop","Ralph Loop替代方案","Ralph Loop安装指南"],"ja":["AIエージェント","Ralph Loopセルフチェック","セキュリティチェックツール","コードスキャン","修復の反復","セキュリティ問題のエスカレート","Ralph Loopの使い方","Ralph Loopの代替","Ralph Loopのセットアップガイド"],"ko":["AI 에이전트","랄프 루프 자기 검사","보안 점검 도구","코드 스캔","반복적인 수정","보안 문제升级","랄프 루프 사용 방법","랄프 루프 대안","랄프 루프 설치 가이드"],"es":["herramientas de AI","seguridad de commits","Self-Check","Ralph Loop","cómo usar Self-Check","alternativas a Self-Check","instalación de Self-Check","guía de configuración de Self-Check"],"fr":["outils d''IA","sécurité des commits","Self-Check","Ralph Loop","comment utiliser Self-Check","alternatives à Self-Check","installation de Self-Check","guide de configuration de Self-Check"],"de":["KI-Tools","Sicherheit von Commits","Self-Check","Ralph Loop","wie man Self-Check verwendet","Alternativen zu Self-Check","Installation von Self-Check","Konfigurationsanleitung für Self-Check"],"pt":["ferramentas de IA","self-check","Ralph Loop","segurança do código","como usar self-check","alternativas ao self-check","self-check vs outras ferramentas","instalação do self-check","guia de configuração do self-check"],"ru":["ИИ Агенты","самопроверка","Ralph Loop","безопасность кода","как использовать самопроверку","альтернативы самопроверке","самопроверка vs другие инструменты","установка самопроверки","руководство по настройке самопроверки"],"ar":["أدوات الذكاء الاصطناعي","فحص ذاتي","RALPH Loop","أمن الكود","كيفية استخدام فحص ذاتي","بديلات فحص ذاتي","فحص ذاتي مقابل أدوات أخرى","تثبيت فحص ذاتي","دليل إعداد فحص ذاتي"]}},"owner":"agairola","repo":"securing-ralph-loop","repoPath":"agairola/securing-ralph-loop","stars":4,"forks":0,"updatedAt":"2026-02-09T08:27:39Z","topics":[],"category":"community","skillMd":{"name":"self-check","description":"Pre-commit self-validation for code quality and security","bodyPreview":"# Pre-Commit Self-Check\n\nValidate your changes before committing to ensure code quality and security standards are met.\n\n## Purpose\n\nThis skill performs a comprehensive self-check on staged changes to catch issues before they are committed. It combines code quality checks with security validation.\n\n## What It Checks\n\n### 1. Code Quality\n- Syntax errors in changed files\n- Linting issues (if linter available)\n- Type errors (if type checker available)\n- Test coverage for new code\n\n### 2. Security\n-","body":"# Pre-Commit Self-Check\n\nValidate your changes before committing to ensure code quality and security standards are met.\n\n## Purpose\n\nThis skill performs a comprehensive self-check on staged changes to catch issues before they are committed. It combines code quality checks with security validation.\n\n## What It Checks\n\n### 1. Code Quality\n- Syntax errors in changed files\n- Linting issues (if linter available)\n- Type errors (if type checker available)\n- Test coverage for new code\n\n### 2. Security\n- Hardcoded credentials\n- Injection vulnerabilities\n- Insecure dependencies\n- Debug code and TODO comments\n\n### 3. Git Hygiene\n- Commit message format\n- No large binary files\n- No merge conflict markers\n- No unresolved TODOs marked as blockers\n\n## Usage\n\n```\n/self-check\n```\n\nRun this skill before `git commit` to validate your changes.\n\n## Process\n\n1. **Identify Changes**: Get list of staged files\n2. **Syntax Check**: Ensure code parses correctly\n3. **Security Scan**: Check for common vulnerabilities\n4. **Quality Check**: Run available linters\n5. **Report**: Summarize findings with actionable items\n\n## Output Format\n\n```\n=== Self-Check Results ===\n\nStaged Files: 5\n  - src/handler.py\n  - src/utils.py\n  - tests/test_handler.py\n  - package.json\n  - README.md\n\n[PASS] Syntax Check: All files parse correctly\n[FAIL] Security Check: 2 issues found\n  - src/handler.py:25 - Potential SQL injection\n  - src/utils.py:10 - Hardcoded password\n\n[PASS] Quality Check: No linting errors\n[WARN] Coverage: New code in handler.py not covered by tests\n\nRecommendation: Fix security issues before committing\n```\n\n## Exit Codes\n\n- **0**: All checks passed\n- **1**: Security issues found (blocking)\n- **2**: Quality issues found (warning)\n\n## Integration\n\nThis skill should be run:\n1. Before every commit\n2. As part of the remediation loop\n3. When requested by the orchestrator\n"},"lastSynced":"2026-02-27T01:56:12.825Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing automated syntax and security validation.","zh":"非常适合需要自动化语法和安全性验证的代码审查代理。","ja":"コードレビューエージェントが自動化された構文とセキュリティ検証を必要とする場合に最適です。","ko":" 자동화된 구문 및 보안 유효성을 필요로 하는 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan validación automática de sintaxis y seguridad.","fr":"Parfait pour les agents de revue de code nécessitant une validation automatique de syntaxe et de sécurité.","de":"Perfekt für Code-Review-Agents, die automatisierte Syntax- und Sicherheitsvalidierung benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de validação automatizada de sintaxe e segurança.","ru":"Идеально подходит для Агентов проверки кода, которым требуется автоматизированная проверка синтаксиса и безопасности.","ar":"مثالي لوكلاء مراجعة التعليمات البرمجية الذين يحتاجون إلى التحقق الآلي من بناء الجملة والأمان."},"recommendation":{"en":"Empowers agents to perform comprehensive self-checks on staged changes, validating code quality through syntax checks, linting, and type error detection, while also ensuring security standards are met through iterative fixes and escalation protocols like the Ralph Loop.","zh":"赋予代理执行对暂存更改的综合自我检查的能力，通过语法检查、linting和类型错误检测来验证代码质量，同时也通过迭代修复和升级协议（如Ralph Loop）来确保安全标准得到满足。","ja":"エージェントにステージされた変更に対して包括的な自己チェックを実行する能力を付与し、構文チェック、linting、および型エラー検出によってコードの品質を検証し、同時にRalph Loopのような反復修復とエスカレーションプロトコルを通じてセキュリティ基準が満たされることを保証します。","ko":"에이전트가暂存된 변경 사항에 대한 포괄적인 자체 검사를 수행할 수 있도록하여, 구문 검사, 린팅 및 유형 오류 감지를 통해 코드 품질을 검증하고, 반복 修復 및 에스컬레이션 프로토콜(Ralph Loop)을 통해 보안 표준이 충족되는 것을 보장합니다.","es":"Habilita a los agentes a realizar verificaciones integrales de los cambios en espera, validando la calidad del código a través de comprobaciones de sintaxis, linting y detección de errores de tipo, asegurando también que se cumplan los estándares de seguridad a través de correcciones iterativas y protocolos de escalada como el Ralph Loop.","fr":"Permet aux agents d''effectuer des auto-vérifications complètes sur les modifications en attente, en validant la qualité du code via des vérifications de syntaxe, du linting et de la détection d''erreurs de type, tout en s''assurant que les normes de sécurité sont respectées via des corrections itératives et des protocoles d''escalade tels que le Ralph Loop.","de":"Ermächtigt Agenten, umfassende Selbstprüfungen auf gestaffelten Änderungen durchzuführen, die Codequalität durch Syntaxprüfungen, Linting und Typfehlererkennung zu validieren, während auch sichergestellt wird, dass Sicherheitsstandards durch iterative Korrekturen und Eskalationsprotokolle wie den Ralph Loop eingehalten werden.","pt":"Capacita os agentes a realizar verificações automáticas abrangentes nas alterações em staging, validando a qualidade do código por meio de verificações de sintaxe, linting e detecção de erros de tipo, além de garantir o cumprimento dos padrões de segurança por meio de correções iterativas e protocolos de escalonamento como o Ralph Loop.","ru":"Позволяет агентам выполнять комплексные самопроверки подготовленных изменений, проверяя качество кода с помощью проверки синтаксиса, линтинга и обнаружения ошибок типов, а также обеспечивая соответствие стандартам безопасности за счет итеративных исправлений и протоколов эскалации, таких как Ralph Loop.","ar":"يمكن الوكلاء من إجراء فحوصات ذاتية شاملة على التغييرات المؤقتة، والتحقق من جودة التعليمات البرمجية من خلال فحوصات بناء الجملة، والتدقيق، واكتشاف أخطاء الكتابة، مع ضمان استيفاء معايير الأمان من خلال التصحيحات التكرارية وبروتوكولات التصعيد مثل Ralph Loop."},"useCases":{"en":["Validating code syntax before commit","Detecting security vulnerabilities in staged changes","Automating test coverage analysis for new code"],"zh":["提交前代码语法验证","检测暂存更改中的安全漏洞","自动化新代码的测试覆盖分析"],"ja":["コミット前のコード構文検証","ステージされた変更の中のセキュリティ脆弱性の検出","新しいコードのテストカバレッジ分析の自動化"],"ko":["提交 전 코드 구문 유효성 검사","暂存된 변경 사항中的 보안 취약점 감지","새로운 코드의 테스트 커버리지 분석 자동화"],"es":["Validar la sintaxis del código antes de confirmar","Detectar vulnerabilidades de seguridad en los cambios en espera","Automatizar el análisis de cobertura de pruebas para el nuevo código"],"fr":["Valider la syntaxe du code avant de confirmer","Détecter les vulnérabilités de sécurité dans les modifications en attente","Automatiser l''analyse de la couverture de tests pour le nouveau code"],"de":["Die Syntax des Codes vor dem Commit validieren","Sicherheitslücken in den gestaffelten Änderungen erkennen","Die Testabdeckungsanalyse für den neuen Code automatisieren"],"pt":["Validação da sintaxe do código antes do commit","Detecção de vulnerabilidades de segurança em alterações em staging","Automatização da análise de cobertura de testes para novo código"],"ru":["Проверка синтаксиса кода перед коммитом","Обнаружение уязвимостей безопасности в подготовленных изменениях","Автоматизация анализа покрытия тестами для нового кода"],"ar":["التحقق من صحة بناء جملة التعليمات البرمجية قبل الالتزام","الكشف عن ثغرات الأمان في التغييرات المؤقتة","أتمتة تحليل تغطية الاختبار للتعليمات البرمجية الجديدة"]},"limitations":{"en":["Requires access to staged changes","Dependent on availability of linter and type checker"],"zh":["需要访问暂存更改","依赖于linter和类型检查器的可用性"],"ja":["ステージされた変更へのアクセスが必要","linterと型チェッカーの可用性に依存"],"ko":["暂存된 변경 사항에 대한 액세스가 필요","린터 및 유형 확인器의 가용성에 의존"],"es":["Requiere acceso a los cambios en espera","Depende de la disponibilidad del linter y del comprobador de tipos"],"fr":["Nécessite l''accès aux modifications en attente","Dépend de la disponibilité du linter et du vérificateur de types"],"de":["Benötigt Zugriff auf die gestaffelten Änderungen","Hängt von der Verfügbarkeit des Linters und des Typprüfers ab"],"pt":["Requer acesso às alterações em staging","Dependente da disponibilidade de linter e verificador de tipo"],"ru":["Требует доступ к подготовленным изменениям","Зависит от доступности линтера и проверки типов"],"ar":["يتطلب الوصول إلى التغييرات المؤقتة","يعتمد على توفر أداة التدقيق والتحقق من النوع"]},"version":3},"contentHash":"5419b3c4096f82b15c8468403629089ebf07c64d1516daa4efc86b809d054ebd","qualityScore":51}');
