INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HKUSTDial/DeepEar/DeepEar Analysis Skill', 'DeepEar Analysis Skill', 'HKUSTDial', 'DeepEar', 'community', 'DeepEar Analysis Skill HKUSTDial DeepEar community DeepEar是一个开源框架，用于深度研究和金融信号追踪。它提供了强大的数据分析和机器学习能力 DeepEarはディープリサーチとファイナンシャルシグナル追跡のためのオープンソースフレームワークです。強力なデータ分析と機械学習能力を提供します DeepEar는 딥 리서치 및 금융 신호 추적을 위한 오픈소스 프레임워크입니다. 강력한 데이터 분석 및 기계 학습 능력을 제공합니다 DeepEar es un marco de investigación y seguimiento de señales financieras de código abierto para desarrolladores DeepEar est un cadre de recherche et de suivi des signaux financiers open source pour les développeurs DeepEar ist ein Open-Source-Framework für Forschung und Finanzsignal-Tracking für Entwickler DeepEar Analysis Skill é uma estrutura de código aberto para pesquisa profunda e rastreamento de sinais financeiros. DeepEar Analysis Skill - открытая платформа для глубокого исследования и отслеживания финансовых сигналов. مهارة تحليل DeepEar هي إطار مفتوح المصدر للبحث العميق وتتبع الإشارات المالية. DeepEar ｜ 顺风耳 An open-source framework for Deep Research and Financial Signal Tracking. 一个用于深度研究与金融信号追踪的开源框架。 DeepEar AIエージェント 深度研究 金融信号追踪 开源框架 如何使用DeepEar DeepEar安装指南 DeepEar vs 其他框架 DeepEar ｜ 顺风耳 An open-source framework for Deep Research and Financial Signal Tracking. 一个用于深度研究与金融信号追踪的开源框架。');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lvndry/jazz/investment-analysis', 'community', 'lvndry', 'jazz', 'lvndry/jazz', 'investment-analysis', 0, 0, 51, '2026-03-04T13:07:01.763Z', '2026-03-04T14:16:00.758Z', '858b101453c76d9d994e9314d48b0e8b946044341f581586a6fd124d1d39f8bc', '{"id":"lvndry/jazz/investment-analysis","name":"investment-analysis","description":{"zh":"Jazz是一个强大的CLI，用于创建具有投资分析能力的自主AI代理","ja":"Jazzは投資分析能力を持つ自律的なAIエージェントを作成するための強力なCLIです","ko":"Jazz는 투자 분석 능력을 갖춘 자율적인 AI 에이전트를 생성하기 위한 강력한 CLI입니다","es":"Jazz es una CLI que permite crear agentes de IA autónomos con capacidades del mundo real para análisis de inversión","fr":"Jazz est une CLI qui vous permet de créer des agents d''IA autonomes avec des capacités du monde réel pour analyse d''investissement","de":"Jazz ist eine CLI, die es ermöglicht, autonome KI-Agenten mit realen Fähigkeiten für Investitionsanalyse zu erstellen","pt":"Jazz é uma CLI poderosa que permite criar agentes de IA autônomos com capacidades do mundo real para análise de investimento","ru":"Jazz - это мощная CLI, которая позволяет создавать автономных ИИ агентов с реальными возможностями для анализа инвестиций","ar":"جاز هي واجهة سطر أوامر قوية تمكن من إنشاء وكلاء ذكاء اصطناعي مستقلين بقدرات العالم الحقيقي لتحليل الاستثمار","en":"Jazz is a powerful CLI that lets you create autonomous AI agents with real-world capabilities."},"seo":{"title":{"zh":"投资分析AI代理","ja":"投資分析AIエージェント","ko":"투자 분석 AI 에이전트","es":"Análisis de Inversión con Agentes de IA","fr":"Analyse d''Investissement avec Outils d''IA","de":"Investitionsanalyse mit KI-Agenten","pt":"Análise de Investimento com Agentes de IA","ru":"ИИ Агенты для Анализа Инвестиций","ar":"تحليل الاستثمار مع وكلاء الذكاء الاصطناعي","en":"investment-analysis"},"description":{"zh":"Jazz是一个强大的CLI，用于创建具有投资分析能力的自主AI代理","ja":"Jazzは投資分析能力を持つ自律的なAIエージェントを作成するための強力なCLIです","ko":"Jazz는 투자 분석 능력을 갖춘 자율적인 AI 에이전트를 생성하기 위한 강력한 CLI입니다","es":"Jazz es una CLI que permite crear agentes de IA autónomos con capacidades del mundo real para análisis de inversión","fr":"Jazz est une CLI qui vous permet de créer des agents d''IA autonomes avec des capacités du monde réel pour analyse d''investissement","de":"Jazz ist eine CLI, die es ermöglicht, autonome KI-Agenten mit realen Fähigkeiten für Investitionsanalyse zu erstellen","pt":"Jazz é uma CLI poderosa que permite criar agentes de IA autônomos com capacidades do mundo real para análise de investimento","ru":"Jazz - это мощная CLI, которая позволяет создавать автономных ИИ агентов с реальными возможностями для анализа инвестиций","ar":"جاز هي واجهة سطر أوامر قوية تمكن من إنشاء وكلاء ذكاء اصطناعي مستقلين بقدرات العالم الحقيقي لتحليل الاستثمار","en":"Jazz is a powerful CLI that lets you create autonomous AI agents with real-world capabilities."},"definition":{"en":"Jazz is a powerful CLI that lets you create autonomous AI agents with real-world capabilities."},"features":{"zh":["支持投资数据分析","自主决策能力","集成机器学习算法","CLI界面易用","支持多种投资策略"],"ja":["投資データ分析をサポート","自律的な意思決定能力","機械学習アルゴリズムを統合","CLIインターフェースが使いやすい","複数の投資戦略をサポート"],"ko":["투자 데이터 분석 지원","자율적인 의사 결정 능력","기계 학습 알고리즘 통합","CLI 인터페이스가 쉽게 사용","다양한 투자 전략 지원"],"es":["Creación de agentes de IA autónomos","Análisis de inversión con capacidades del mundo real","Integración con CLI para fácil uso","Desarrollo de aplicaciones personalizadas","Análisis de datos y generación de informes"],"fr":["Création d''agents d''IA autonomes","Analyse d''investissement avec des capacités du monde réel","Intégration avec CLI pour un usage facile","Développement d''applications personnalisées","Analyse de données et génération de rapports"],"de":["Erstellung von autonomen KI-Agenten","Investitionsanalyse mit realen Fähigkeiten","Integration mit CLI für einfache Bedienung","Entwicklung von individuellen Anwendungen","Datenanalyse und Berichterstellung"],"pt":["Criação de agentes de IA autônomos","Análise de investimento com capacidades do mundo real","Integração com Jazz CLI","Desenvolvimento de soluções personalizadas","Suporte a múltiplas linguagens de programação"],"ru":["Создание автономных ИИ агентов","Анализ инвестиций с реальными возможностями","Интеграция с Jazz CLI","Разработка индивидуальных решений","Поддержка нескольких языков программирования"],"ar":["إنشاء وكلاء ذكاء اصطناعي مستقلين","تحليل الاستثمار بقدرات العالم الحقيقي","التكامل مع Jazz CLI","تطوير حلول مخصصة","دعم لغات برمجة متعددة"]},"keywords":{"zh":["如何使用Jazz CLI","什么是投资分析AI代理","Jazz CLI替代品","Jazz CLI与其他工具的比较","Jazz CLI安装","Jazz CLI设置指南","投资分析工具","AI代理开发","机器学习在投资分析中的应用"],"ja":["Jazz CLIの使い方","投資分析AIエージェントとは","Jazz CLIの代替品","Jazz CLIと他のツールの比較","Jazz CLIのインストール","Jazz CLIの設定ガイド","投資分析ツール","AIエージェント開発","機械学習を投資分析に適用"],"ko":["Jazz CLI 사용 방법","투자 분석 AI 에이전트란","Jazz CLI 대체품","Jazz CLI와 다른 도구 비교","Jazz CLI 설치","Jazz CLI 설정 가이드","투자 분석 도구","AI 에이전트 개발","기계 학습을 투자 분석에 적용"],"es":["cómo usar Jazz para análisis de inversión","qué es un agente de IA","Jazz alternativa","Jazz vs otros agentes de IA","instalación de Jazz","guía de configuración de Jazz","análisis de inversión con IA","desarrollo de aplicaciones de IA"],"fr":["comment utiliser Jazz pour analyse d''investissement","qu''est-ce qu''un outil d''IA","Jazz alternative","Jazz vs autres outils d''IA","installation de Jazz","guide de configuration de Jazz","analyse d''investissement avec IA","développement d''applications d''IA"],"de":["wie man Jazz für Investitionsanalyse verwendet","was ist ein KI-Agent","Jazz Alternative","Jazz vs andere KI-Agenten","Installation von Jazz","Einrichtungsanleitung für Jazz","Investitionsanalyse mit KI","Entwicklung von KI-Anwendungen"],"pt":["como usar agentes de IA","o que é análise de investimento","Jazz CLI alternative","Jazz vs outros agentes de IA","instalar Jazz CLI","guia de configuração do Jazz"],"ru":["как использовать ИИ агентов","что такое анализ инвестиций","Jazz CLI альтернатива","Jazz vs другие ИИ агенты","установить Jazz CLI","руководство по настройке Jazz"],"ar":["كيفية استخدام وكلاء الذكاء الاصطناعي","ما هو تحليل الاستثمار","بديل Jazz CLI","Jazz مقابل وكلاء الذكاء الاصطناعي الآخرون","تثبيت Jazz CLI","دليل إعداد Jazz"]}},"owner":"lvndry","repo":"jazz","repoPath":"lvndry/jazz","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.763Z","topics":[],"category":"community","skillMd":{"name":"investment-analysis","description":"In-depth analysis of investment assets (gold, silver, bitcoin, equities, etc.) to support investment decisions. Use when the user wants to understand an assets current state, market analysis, patterns, forecasts, or whether it fits their situation. Triggers on investment analysis, analyze gold/bitcoin/silver, should I invest in X, current state of X, market analysis, is X a good investment.","bodyPreview":"# Investment Analysis\n\nInvestment decisions affect real wealth and real lives. This skill provides in-depth analysis—grounded in investor frameworks (value, macro, growth, risk)—to support your decisions. When the analysis supports a view, give a **clear, sourced, nuanced conclusion** tailored to the user''s profile. Avoid vague hedging; substance and conviction (when justified) build trust.\n\nFor mindset and frameworks, see [references/investment-mindset.md](references/investment-mindset.md).\n\n##","body":"# Investment Analysis\n\nInvestment decisions affect real wealth and real lives. This skill provides in-depth analysis—grounded in investor frameworks (value, macro, growth, risk)—to support your decisions. When the analysis supports a view, give a **clear, sourced, nuanced conclusion** tailored to the user''s profile. Avoid vague hedging; substance and conviction (when justified) build trust.\n\nFor mindset and frameworks, see [references/investment-mindset.md](references/investment-mindset.md).\n\n## When to Use\n\n- User wants to analyze an asset (gold, silver, bitcoin, a stock, ETF, or commodity)\n- User asks \"should I invest in X?\" or \"is X a good investment?\"\n- User wants current market state, patterns, or forecasts for an asset\n- User wants to know if an asset fits their goals, risk, or time horizon\n- User asks for \"investment analysis\", \"market analysis\", or \"pattern recognition\" for an asset\n\n## Disclaimer & Scope\n\n**This is not licensed investment, tax, or legal advice.** No guarantee of returns. For major decisions (large sums, complex situations, tax/estate), recommend consulting a qualified professional.\n\n**Do give actionable conclusions** when analysis supports them: sourced, justified, tied to the user''s goals, risk, and horizon. The user deserves a clear view, not a hand-off. State confidence level and caveats.\n\n## Workflow\n\n1. **Clarify asset and user situation**: Which asset? User''s goals (growth, income, hedge), risk tolerance, time horizon, and (if shared) existing exposure.\n2. **Gather current state**: Price, volume, recent trend, key levels. Use recent data; cite source and date.\n3. **Apply investment mindset**: Use frameworks from [references/investment-mindset.md](references/investment-mindset.md)—Buffett/Munger (value, margin of safety), Dalio (macro), Lynch (story), Marks (risk/cycles), Graham (intrinsic value)—to deepen analysis. Avoid shallow takes.\n4. **Analyze patterns and context**: Technical patterns, sentiment, on-chain (for crypto), macro context (rates, inflation, geopolitics) where relevant.\n5. **Consider forecasts and previsions**: What analysts or models say (bull/bear cases). Label as outlook, not fact.\n6. **Assess fit for situation**: Does the asset align with the user''s goals, risk, and horizon? Pros and cons in that context.\n7. **Present analysis**: Structured report with current state, patterns, outlook, fit, risks, and caveats. When analysis supports a view, state it clearly—e.g. \"For your profile, a small allocation (X–Y%) could fit because [sourced reasons]\" or \"Given your horizon and risk tolerance, this asset is likely misaligned—[reasons].\"\n\n## What to Analyze\n\n### Current State\n\n- **Price**: Current level, recent range (e.g. 30/90 days), key support/resistance if useful\n- **Volume / liquidity**: Where relevant (e.g. crypto, equities)\n- **Trend**: Short- and medium-term direction; cite time frame\n- **Context**: Rates, inflation, dollar, geopolitics—only what''s relevant to the asset\n\nCite source and date for every number (e.g. \"BTC price as of [date] per [source]\").\n\n### Pattern Recognition\n\n- **Technical**: Trends, ranges, common patterns (e.g. breakout, consolidation). Describe, don''t guarantee.\n- **Sentiment**: Fear/greed, positioning, flows—when data is available and relevant\n- **On-chain (crypto)**: Active addresses, supply in profit/loss, exchange flows—when available\n- **Seasonal / cyclical**: Historical patterns (e.g. gold in certain periods); state that past ≠ future\n\nLabel clearly: \"pattern observed\" vs \"forecast or interpretation.\"\n\n### Forecasts and Previsions\n\n- **Analyst views**: Summarize bull/bear cases; name source and date\n- **Model-based**: E.g. valuation bands, trend extrapolation—state assumptions\n- **Scenarios**: Best / base / worst case with clear \"if X then Y\" and caveats\n\nNo single \"this will happen\" claim; present range of views and uncertainty.\n\n### Fit for User Situation\n\n- **Goals**: Growth vs income vs hedge vs diversification\n- **Risk tolerance**: Volatility, drawdowns, loss capacity\n- **Time horizon**: Short vs long term; liquidity needs\n- **Existing exposure**: Already heavy in the asset? Diversification benefit?\n\nOutput: A clear conclusion with reasoning. E.g. \"Given [situation], I''d lean [for/against/neutral] because [sourced reasons]. Consider [suggested allocation or action] if [conditions].\" Tie every view to sources and profile.\n\n## Output Format\n\n```markdown\n# Investment Analysis: [Asset] — [Date]\n\n## Summary\n\n[2–4 sentences: current state, main pattern/outlook, and fit with user situation. Include a clear conclusion when analysis supports it—e.g. \"For a long-term, risk-tolerant profile, a small allocation could fit; for short horizons, likely misaligned.\"]\n\n## Your Situation (as shared)\n\n- Goals: [e.g. long-term growth, hedge inflation]\n- Risk: [e.g. moderate, can tolerate 20% drawdown]\n- Horizon: [e.g. 5+ years]\n- [Optional] Current exposure: [e.g. none, 5% in gold]\n\n## Current Market State\n\n- **Price / level**: [value] as of [date] ([source])\n- **Recent trend**: [e.g. up/down/sideways over 30/90 days]\n- **Context**: [rates, inflation, or other relevant factor in 1–2 lines]\n\n## Patterns & Indicators\n\n- [Pattern 1]: [What you see and time frame]\n- [Pattern 2]: [What you see and time frame]\n- [Sentiment / on-chain if relevant]: [1–2 lines]\n\n## Outlook & Previsions\n\n- **Bull case**: [Short summary + source/date if applicable]\n- **Bear case**: [Short summary]\n- **Base case / range**: [If useful, with assumptions stated]\n\n## Fit for Your Situation\n\n- **Pros**: [How it could align with goals/risk/horizon]\n- **Cons**: [Risks or misalignment with situation]\n- **Conclusion**: [Clear view with reasoning. E.g. \"For your profile (long-term, moderate risk), a 2–5% allocation could fit as a diversification/hedge—because [sourced reasons]. I''d avoid or minimize if [conditions].\" Or \"Given your short horizon, I''d lean against—[reasons].\" State confidence and caveats.]\n\n## Risks & Caveats\n\n- [Risk 1]\n- [Risk 2]\n- Past performance does not guarantee future results. For large or complex decisions, consult a qualified professional.\n```\n\n## Asset Coverage\n\n- **Precious metals**: Gold, silver—price, trend, macro context (real rates, dollar, geopolitics), common use as hedge.\n- **Crypto**: Bitcoin (and optionally major altcoins)—price, volume, on-chain metrics, sentiment, regulatory/macro tailwinds/risks.\n- **Equities / ETFs**: Single names or broad indices—valuation, trend, sector context; same \"current state + patterns + outlook + fit\" structure.\n\nFor asset-specific metrics and data sources, see [references/assets.md](references/assets.md).\n\n## Time Awareness\n\n- **User specifies a period** (e.g. \"last 6 months\", \"2024\") → Use that period for trends and data.\n- **No period given** → Use **most recent** data (e.g. current price, last 30/90 days for trend).\n- Always state the date and source for prices and metrics (e.g. \"as of [date] per [source]\").\n\n## Sources\n\n- **Prices / market data**: Exchange or index provider, reputable aggregator (e.g. CoinGecko for crypto). Cite URL or name and date.\n- **On-chain (crypto)**: Public dashboards (e.g. Glassnode, CryptoQuant). Cite name and date.\n- **Macro**: Central banks, statistical offices, widely cited data. Cite source and date.\n- **Analyst views**: Named source and date; treat as opinion, not fact.\n\nPrefer primary or well-known sources. Never invent data.\n\n## Anti-Patterns\n\n- ❌ Giving conclusions without sources, reasoning, or profile fit (vague advice erodes trust)\n- ❌ Over-hedging when analysis supports a view—the user deserves a clear take\n- ❌ Guaranteeing returns or price levels\n- ❌ Using data without source and date\n- ❌ Presenting one view as certainty; show range and uncertainty\n- ❌ Ignoring user situation; always tie fit to goals, risk, and horizon\n- ❌ Skipping risks and caveats\n"},"lastSynced":"2026-03-04T14:16:00.758Z","agentAnalysis":{"suitability":{"en":"Perfect for Financial Analysis Agents needing in-depth investment insights grounded in investor frameworks like value, macro, growth, and risk","zh":"非常适合需要深入投资洞察的金融分析代理，基于像价值、宏观、增长和风险这样的投资者框架","ja":"投資家フレームワークのような価値、 マクロ、成長、リスクに基づく詳細な投資洞察が必要な金融分析エージェントに最適","ko":"가치, 매크로, 성장, 리스크와 같은 투자자 프레임워크에 기반한 심층적인 투자 통찰이 필요한 금융 분석 에이전트에게 완벽","es":"Perfecto para Agentes de Análisis Financiero que necesitan conocimientos en profundidad sobre inversiones basados en marcos de inversores como valor, macro, crecimiento y riesgo","fr":"Parfait pour les Agents d''Analyse Financière ayant besoin d''informations approfondies sur les investissements ancrées dans les cadres d''investisseurs tels que la valeur, le macro, la croissance et le risque","de":"Perfekt für Finanzanalyse-Agenten, die umfassende Investitionserkenntnisse benötigen, die auf Investoren-Frameworks wie Wert, Makro, Wachstum und Risiko basieren","pt":"Perfeito para Agentes de Análise Financeira que necessitam de insights de investimento aprofundados baseados em estruturas de investidores como valor, macro, crescimento e risco","ru":"Идеально для Финансовых Аналитических Агентов, которым требуются глубокие инвестиционные идеи, основанные на инвесторских рамках, таких как стоимость, макро, рост и риск","ar":"مثالي للوكلاء المحللين الماليين الذين يحتاجون إلى رؤى استثمارية متعمقة ترتكز على إطارات المستثمرين مثل القيمة والماكرو والنمو والمخاطر"},"recommendation":{"en":"Empowers agents to provide clear, sourced, nuanced conclusions tailored to user profiles, leveraging frameworks and mindsets outlined in references like investment-mindset.md, and supporting decisions with substance and conviction","zh":"赋予代理提供清晰、有来源、细致入微的结论，根据用户配置文件量身定制，利用 investment-mindset.md 中概述的框架和思维方式，并以实质和信念支持决策","ja":"エージェントがユーザープロファイルに合わせたクリアでソースがあり、ニュアンスのある結論を提供できるようにし、investment-mindset.md に概説されているフレームワークとマインドセットを利用し、意思決定を実質と信念でサポートする","ko":"에이전트가 사용자 프로필에 맞춰 명확하고 출처가があり며细致한 결론을 제공할 수 있도록 하며, investment-mindset.md에概説된 프레임워크와 마인드셋을 利用하며, 의사결정을 실질과 信念으로 지원","es":"Habilita a los agentes a proporcionar conclusiones claras, fundamentadas, matizadas y adaptadas a los perfiles de usuario, aprovechando los marcos y mentalidades descritos en referencias como investment-mindset.md, y apoyando las decisiones con sustancia y convicción","fr":"Permet aux agents de fournir des conclusions claires, étayées, nuancées et adaptées aux profils d''utilisateur, en exploitant les cadres et les mentalités décrits dans des références comme investment-mindset.md, et en étayant les décisions avec substance et conviction","de":"Ermächtigt die Agenten, klare, belegte, differenzierte und an die Benutzerprofile angepasste Schlussfolgerungen zu liefern, indem sie Frameworks und Mindsets nutzen, die in Referenzen wie investment-mindset.md beschrieben sind, und die Entscheidungen mit Inhalt und Überzeugung unterstützen","pt":"Habilita os agentes a fornecer conclusões claras, fundamentadas, matizadas e personalizadas para perfis de usuário, utilizando estruturas e mentalidades delineadas em referências como investment-mindset.md, e apoiando decisões com substância e convicção","ru":"Наделяет агентов возможностью предоставлять ясные, обоснованные, нюансированные выводы, адаптированные к профилям пользователей, используя рамки и мышление, изложенные в справочных материалах, таких как investment-mindset.md, и поддерживая решения содержанием и убеждением","ar":"تمكن الوكلاء من تقديم استنتاجات واضحة ومصدرة ومتحفظة ومصممة لملفات تعريف المستخدم، مستخدمة الإطارات والاتجاهات المحددة في المراجع مثل investment-mindset.md، ودعم القرارات بالمادة والاقتناع"},"useCases":{"en":["Analyzing investment opportunities based on macroeconomic trends","Generating growth-oriented investment portfolios","Evaluating risk management strategies for diversified investments"],"zh":["基于宏观经济趋势分析投资机会","生成增长导向的投资组合","评估多元化投资的风险管理策略"],"ja":["マクロ経済トレンドに基づく投資機会の分析","成長指向の投資ポートフォリオの生成","多元化投資のリスク管理戦略の評価"],"ko":["매크로 경제 트렌드에 기반한 투자 기회의 분석","성장 지향 투자 포트폴리오의 생성","다변화 투자의 리스크 관리 전략의 평가"],"es":["Análisis de oportunidades de inversión basadas en tendencias macroeconómicas","Generación de carteras de inversión orientadas al crecimiento","Evaluación de estrategias de gestión de riesgos para inversiones diversificadas"],"fr":["Analyse des opportunités d''investissement basées sur les tendances macroéconomiques","Génération de portefeuilles d''investissement axés sur la croissance","Évaluation des stratégies de gestion des risques pour les investissements diversifiés"],"de":["Analyse von Investitionsmöglichkeiten basierend auf makroökonomischen Trends","Erstellung von wachstumsorientierten Anlageportfolios","Bewertung von Risikomanagement-Strategien für diversifizierte Investitionen"],"pt":["Analisar oportunidades de investimento com base em tendências macroeconômicas","Gerar portfólios de investimento orientados ao crescimento","Avaliar estratégias de gestão de riscos para investimentos diversificados"],"ru":["Анализ инвестиционных возможностей на основе макроэкономических тенденций","Генерация портфелей инвестиций, ориентированных на рост","Оценка стратегий управления рисками для диверсифицированных инвестиций"],"ar":["تحليل فرص الاستثمار على أساس الاتجاهات الاقتصادية الكلية","генерация محفظة استثمارية متجهة نحو النمو","تقييم استراتيجيات إدارة المخاطر للاستثمارات المتنوعة"]},"limitations":{"en":["Requires understanding of investor frameworks and mindsets","Dependent on quality and accuracy of input data"],"zh":["需要了解投资者框架和思维方式","依赖输入数据的质量和准确性"],"ja":["投資家フレームワークとマインドセットの理解が必要","入力データの品質と正確性に依存"],"ko":["투자자 프레임워크와 마인드셋의 이해가 필요","입력 데이터의 품질과 정확성에 의존"],"es":["Requiere comprensión de los marcos y mentalidades de los inversores","Dependiente de la calidad y precisión de los datos de entrada"],"fr":["Nécessite une compréhension des cadres et des mentalités des investisseurs","Dépend de la qualité et de l''exactitude des données d''entrée"],"de":["Benötigt Verständnis für Investoren-Frameworks und -Mindsets","Abhängig von Qualität und Genauigkeit der Eingabedaten"],"pt":["Exige compreensão das estruturas e mentalidades de investidores","Depende da qualidade e precisão dos dados de entrada"],"ru":["Требует понимания инвесторских рамок и мышления","Зависит от качества и точности входных данных"],"ar":["يتطلب فهم الإطارات والاتجاهات للمستثمرين","يعتمد على جودة ودقة بيانات الإدخال"]},"version":3},"contentHash":"858b101453c76d9d994e9314d48b0e8b946044341f581586a6fd124d1d39f8bc","qualityScore":51}');
