INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HKTITAN/kheMessage/editor-core', 'editor-core', 'HKTITAN', 'kheMessage', 'community', 'editor-core HKTITAN kheMessage community editor-core是一个基于浏览器的编辑器，支持块编辑、链接分享、QR码和本地版本历史，无需后端 editor-coreはブラウザベースのエディターで、ブロックエディター、リンクシェア、QRコード、ローカルバージョン履歴をサポートします。バックエンドは不要です editor-core는 브라우저 기반 편집기로, 블록 편집기, 링크 공유, QR 코드, 로컬 버전 기록을 지원하며 백엔드가 필요 없습니다 Editor-core es un editor en navegador que almacena contenido en la URL, con características como edición de bloques, compartición por enlace y código QR Editor-core est un éditeur en navigateur qui stocke le contenu dans l''URL, avec des fonctionnalités comme édition de blocs, partage par lien et code QR Editor-core ist ein Browser-Editor, der Inhalte in der URL speichert, mit Funktionen wie Blockbearbeitung, Link- und QR-Code-Teilen O Editor-Core é um editor em navegador que armazena conteúdo na URL, com recursos de edição de blocos, compartilhamento via link ou QR e histórico de versões locais Editor-Core - браузерный редактор, который хранит контент в URL, с функциями блокового редактирования, обмена по ссылке или QR и локальной истории версий Editor-Core هو محرر متصفح يحفظ المحتوى في URL، مع ميزات تحرير الكتلة، ومشاركة عبر الرابط أو QR وتاريخ إصدارات محلي In-browser editor that stores content in the URL. Block editor, share by link, QR, local version history. No backend, PWA. 如何使用editor-core 什么是editor-core editor-core替代品 editor-core与其他工具比较 editor-core安装 editor-core设置指南 基于浏览器的编辑器 AI工具 块编辑 In-browser editor that stores content in the URL. Block editor, share by link, QR, local version history. No backend, PWA.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RedHat-UX/next-gen-ui-agent/pants-format-check', 'community', 'RedHat-UX', 'next-gen-ui-agent', 'RedHat-UX/next-gen-ui-agent', 'pants-format-check', 0, 0, 51, '2026-03-04T13:07:01.833Z', '2026-03-04T14:44:26.609Z', 'ceae48111e2ff872a4dbbaa8f94dab8219b480b9d01795147dddc7759361c71d', '{"id":"RedHat-UX/next-gen-ui-agent/pants-format-check","name":"pants-format-check","description":{"zh":"一栈一栈一栈栀栁栁栀栁栀栁栀栁","ja":"一栈一栈一栈栀栁栁栀栁栀栁栀栁","ko":"一栈一栈一栈栀栁栁栀栁栀栁栀栁","es":"pants-format-check es un agente de IA que genera componentes UI personalizados y ricos basados en la entrada del usuario, el historial de chat y los datos de backend proporcionados por otros agentes","fr":"pants-format-check est un agent d''IA qui génère des composants UI personnalisés et riches basés sur l''entrée de l''utilisateur, l''historique de chat et les données de backend fournies par d''autres agents","de":"pants-format-check ist ein KI-Agent, der personalisierte und reiche UI-Komponenten basierend auf der Benutzereingabe, der Chat-Historie und den von anderen Agents bereitgestellten Backend-Daten generiert","pt":"O agente de IA pants-format-check gera componentes de UI ricos e personalizados com base em prompts de usuário, histórico de chat e dados de backend.","ru":"ИИ Агент pants-format-check генерирует персонализированные и богатые компоненты UI на основе пользовательских запросов, истории чата и данных бэкенда.","ar":"توليد أداة الذكاء الاصطناعي pants-format-check مكونات واجهة المستخدم الغنية والمخصصة بناءً على تأشيرات المستخدم وسجل المحادثة والبيانات الخلفية.","en":"The goal of this AI agent is to generate personalised and rich UI components based on the user prompt, chat history and backend data provided by other agents in your AI assistant."},"seo":{"title":{"zh":"AI栁栀 - 一栈一栈一栈栀栁","ja":"AI栁栀 - 一栈一栈一栈栀栁","ko":"오뮡 와 - 一栈一栈一栈栀栁","es":"Herramie