INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('openakita/openakita/file-manager', 'community', 'openakita', 'openakita', 'openakita/openakita', 'file-manager', 0, 0, 51, '2026-03-01T12:47:24.717Z', '2026-03-01T13:52:50.244Z', '59a971e96b5d6073c1129e83a5033475c518b7b622bc672e9e13ad9bf4005a6a', '{"id":"openakita/openakita/file-manager","name":"file-manager","description":{"zh":"文件管理器是一个开源的AI助手框架，提供强大的文件管理功能","ja":"ファイルマネージャーは、オープンソースのAIアシスタントフレームワークであり、強力なファイル管理機能を提供します","ko":"파일 매니저는 오픈소스 AI 어시스턴트 프레임워크로서 강력한 파일 관리 기능을 제공합니다","es":"El framework file-manager es una arquitectura de agente de IA de código abierto para desarrolladores. Permite la integración de habilidades y agentes en proyectos de IA","fr":"Le framework file-manager est une architecture d''agent IA open-source pour les développeurs. Il permet l''intégration de compétences et d''agents dans les projets d''IA","de":"Das file-manager-Framework ist eine Open-Source-KI-Architektur für Entwickler. Es ermöglicht die Integration von Fähigkeiten und Agenten in KI-Projekten","pt":"O file-manager é uma estrutura de assistente de IA de código aberto com habilidades e arquitetura de agente","ru":"Файловый менеджер - это открытый ИИ агент с навыками и архитектурой агента","ar":"مدير الملفات هو إطار مساعد ذكي مفتوح المصدر مع مهارات وهيكل وكيل","en":"An open-source AI assistant framework with skills and agent architecture"},"seo":{"title":{"zh":"AI智能代理 - 文件管理器","ja":"AIエージェント - ファイルマネージャー","ko":"AI 에이전트 - 파일 매니저","es":"AI Agentes: file-manager para desarrolladores","fr":"Outils IA: file-manager pour les développeurs","de":"KI-Tools: file-manager für Entwickler","pt":"Ferramentas de Agente de IA: file-manager","ru":"ИИ Агенты: файловый менеджер","ar":"أدوات الوكيل الذكي: مدير الملفات","en":"file-manager"},"description":{"zh":"文件管理器是一个开源的AI助手框架，提供强大的文件管理功能","ja":"ファイルマネージャーは、オープンソースのAIアシスタントフレームワークであり、強力なファ