INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aget-framework/template-analyst-aget/aget-check-evolution', 'community', 'aget-framework', 'template-analyst-aget', 'aget-framework/template-analyst-aget', 'aget-check-evolution', 0, 0, 51, '2026-02-26T08:25:24.796Z', '2026-02-26T12:45:19.188Z', '62225f596bebfa5e6aa19d9cc2fdf738236aaf21bb057aece1bfe1c5b54b6cb3', '{"id":"aget-framework/template-analyst-aget/aget-check-evolution","name":"aget-check-evolution","description":{"zh":"aget-check-evolution是一个用于数据分析和洞察的分析模板，扩展了Advisor架构。它提供了强大的数据分析和可视化功能","ja":"aget-check-evolutionはデータ分析と洞察のための分析テンプレートで、Advisorアーキテクチャを拡張しています。強力なデータ分析と可視化機能を提供します","ko":"aget-check-evolution은 데이터 분석과洞察력을 위한 분석 템플릿으로 Advisor 아키텍처를 확장합니다. 강력한 데이터 분석과 시각화 기능을 제공합니다","es":"aget-check-evolution es una plantilla analítica que extiende el arquetipo Advisor para realizar análisis de datos avanzado y generar insights automatizados. Proporciona un framework técnico para integrar con Python, Node.js y herramientas de data science.","fr":"aget-check-evolution est un modèle analytique étendant l''archétype Advisor pour l''analyse de données et la génération d''insights automatisés. Il offre un framework technique pour l''intégration avec Python, Node.js et les outils de data science.","de":"aget-check-evolution ist eine analytische Vorlage, die den Advisor-Archetyp für Datenanalyse und automatisierte Insights-Erzeugung erweitert. Sie bietet ein technisches Framework für die Integration mit Python, Node.js und Data-Science-Tools.","pt":"aget-check-evolution é um template analítico para análise de dados e insights, estendendo o arquétipo Advisor","ru":"aget-check-evolution - это аналитический шаблон для анализа данных и инсайтов, расширяющий архетип Advisor","ar":"aget-check-evolution هو قالب تحليلي للتحليل البياني والرؤى، يمتد إلى نمط Advisor","en":"Analytical template for data analysis and insig