INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dipenmagdani/portfolio-v2/programmatic-seo', 'programmatic-seo', 'dipenmagdani', 'portfolio-v2', 'community', 'programmatic-seo dipenmagdani portfolio-v2 community 程序化SEO是一种利用AI智能工具自动化SEO优化的技术，用于提高开发效率和网站性能 プログラムSEOは、AIエージェントを利用してSEO最適化を自動化する技術で、開発効率とウェブサイトパフォーマンスを向上 프로그래밍 SEO는 AI 에이전트를 사용하여 SEO 최적화를 자동화하는 기술로 개발 효율성과 웹사이트 성능을 향상 Mi Portfolio presenta herramientas de SEO programático para desarrolladores, mejorando la optimización de sitios web con AI Agentes Mon Portfolio présente des outils de SEO programmé pour les développeurs, améliorant l''optimisation des sites web avec des agents IA Mein Portfolio präsentiert programmatische SEO-Tools für Entwickler, verbessert die Optimierung von Websites mit KI-Agents O programa de SEO programático oferece soluções técnicas para desenvolvedores ИИ Агенты для программного SEO предоставляют технические решения для разработчиков أدوات إدارة محركات البحث البرمجية تقدم حلول تقنية للمانحين My Portfolio 程序化SEO AI智能工具 SEO优化 开发效率 网站性能 React Node.js CLI工具 My Portfolio');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kreuzberg-dev/kreuzberg/kreuzberg', 'community', 'kreuzberg-dev', 'kreuzberg', 'kreuzberg-dev/kreuzberg', 'kreuzberg', 0, 0, 50, '2026-03-04T13:07:01.666Z', '2026-03-04T13:21:56.450Z', '4ec8fa91d9dd48bafcb32556b244d2198f6745dfadfad81fe33d33b8b3f8d316', '{"id":"kreuzberg-dev/kreuzberg/kreuzberg","name":"kreuzberg","description":{"zh":"Kreuzberg 是一个高性能的文档智能库，支持多种编程语言，包括 Rust、Python、Node.js/TypeScript 等","ja":"Kreuzberg は、高性能のドキュメントインテリジェンスライブラリで、Rust、Python、Node.js/TypeScript など複数のプログラミング言語をサポートします","ko":"Kreuzberg는 고성능 문서 인텔리전스 라이브러리로서 Rust, Python, Node.js/TypeScript 등을 포함한 여러 프로그래밍 언어를 지원합니다","es":"Kreuzberg es una biblioteca de inteligencia de documentos de alto rendimiento con núcleo de Rust y enlaces nativos para varios lenguajes","fr":"Kreuzberg est une bibliothèque d''intelligence de documents haute performance avec un noyau Rust et des liens natifs pour plusieurs langages","de":"Kreuzberg ist eine Hochleistungs-Bibliothek für Dokumenten-Intelligenz mit Rust-Kern und nativen Bindings für mehrere Sprachen","pt":"Kreuzberg é uma biblioteca de inteligência de documentos de alto desempenho com núcleo em Rust e vinculações nativas para Python, Node.js/TypeScript, Ruby, Go, Java, C#, PHP e Elixir.","ru":"Kreuzberg - это высокопроизводительная библиотека документальной разведки с ядром на Rust и родными привязками для Python, Node.js/TypeScript, Ruby, Go, Java, C#, PHP и Elixir.","ar":"Kreuzberg هي مكتبة ذكاء المستندات عالية الأداء مع نواة في Rust وربطات الأصلي ل Python و Node.js/TypeScript و Ruby و Go و Java و C# و PHP و Elixir.","en":"A polyglot document intelligence framework with a Rust core. Extract text, metadata, and structured information from PDFs, Office documents, images, and 75+ formats. Available for Rust, Python, Ruby, Java, Go, PHP, Elixir, C#, TypeScript (Node/Bun/Wasm/Deno)- or use via CLI, REST API, or MCP server."},"seo":{"title":{"zh":"Kreuzberg 文档提取框架","ja":"Kreuzberg ドキュメント抽出フレームワーク","ko":"Kreuzberg 문서 추출 프레임워크","es":"Kreuzberg: Extracción de Documentos Inteligentes","fr":"Kreuzberg: Extraction de Documents Intelligents","de":"Kreuzberg: Intelligente Dokumentenextraktion","pt":"Kreuzberg: Extração de Documentos em Rust","ru":"Kreuzberg: Фреймворк для извлечения данных из документов","ar":"Kreuzberg: إطار عمل ذكاء المستندات متعدد اللغات","en":"kreuzberg"},"description":{"zh":"Kreuzberg 是一个高性能的文档智能库，支持多种编程语言，包括 Rust、Python、Node.js/TypeScript 等","ja":"Kreuzberg は、高性能のドキュメントインテリジェンスライブラリで、Rust、Python、Node.js/TypeScript など複数のプログラミング言語をサポートします","ko":"Kreuzberg는 고성능 문서 인텔리전스 라이브러리로서 Rust, Python, Node.js/TypeScript 등을 포함한 여러 프로그래밍 언어를 지원합니다","es":"Kreuzberg es una biblioteca de inteligencia de documentos de alto rendimiento con núcleo de Rust y enlaces nativos para varios lenguajes","fr":"Kreuzberg est une bibliothèque d''intelligence de documents haute performance avec un noyau Rust et des liens natifs pour plusieurs langages","de":"Kreuzberg ist eine Hochleistungs-Bibliothek für Dokumenten-Intelligenz mit Rust-Kern und nativen Bindings für mehrere Sprachen","pt":"Kreuzberg é uma biblioteca de inteligência de documentos de alto desempenho com núcleo em Rust e vinculações nativas para Python, Node.js/TypeScript, Ruby, G...","ru":"Kreuzberg - это высокопроизводительная библиотека документальной разведки с ядром на Rust и родными привязками для Python, Node.js/TypeScript, Ruby, Go, Java...","ar":"Kreuzberg هي مكتبة ذكاء المستندات عالية الأداء مع نواة في Rust وربطات الأصلي ل Python و Node.js/TypeScript و Ruby و Go و Java و C# و PHP و Elixir.","en":"A polyglot document intelligence framework with a Rust core. Extract text, metadata, and structured information from PDFs, Office documents, images, and 75+ ..."},"definition":{"en":"A polyglot document intelligence framework with a Rust core. Extract text, metadata, and structured information from PDFs, Office documents, images, and 75+ formats. Available for Rust, Python, Ruby, Java, Go, PHP, Elixir, C#, TypeScript (Node/Bun/Wasm/Deno)- or use via CLI, REST API, or MCP server."},"features":{"zh":["支持 75+ 格式的文档提取","高性能的文档智能库","支持多种编程语言","包括 PDF、Office 文档、图像等格式","支持 OCR 功能","提供 CLI、REST API 和 MCP 服务器接口"],"ja":["75 種類以上の形式のドキュメント抽出をサポート","高性能のドキュメントインテリジェンスライブラリ","複数のプログラミング言語をサポート","PDF、Office ドキュメント、画像などをサポート","OCR 機能をサポート","CLI、REST API、MCP サーバーインターフェースを提供"],"ko":["75종 이상의 형식의 문서 추출을 지원","고성능 문서 인텔리전스 라이브러리","여러 프로그래밍 언어를 지원","PDF, Office 문서, 이미지 등을 지원","OCR 기능을 지원","CLI, REST API, MCP 서버 인터페이스를 제공"],"es":["Extracción de texto y metadatos de documentos","Reconocimiento óptico de caracteres (OCR) para documentos escaneados","Soporte para 75+ formatos de archivo","Enlaces nativos para Rust, Python, Node.js/TypeScript, Ruby, Go, Java, C#, PHP y Elixir","Interfaz de línea de comandos, API REST y servidor MCP"],"fr":["Extraction de texte et de métadonnées de documents","Reconnaissance optique de caractères (OCR) pour les documents scannés","Prise en charge de 75+ formats de fichiers","Liens natifs pour Rust, Python, Node.js/TypeScript, Ruby, Go, Java, C#, PHP et Elixir","Interface de ligne de commande, API REST et serveur MCP"],"de":["Extraktion von Text und Metadaten aus Dokumenten","Optische Zeichenerkennung (OCR) für gescannte Dokumente","Unterstützung für 75+ Dateiformate","Native Bindings für Rust, Python, Node.js/TypeScript, Ruby, Go, Java, C#, PHP und Elixir","Kommandozeilen-Interface, REST-API und MCP-Server"],"pt":["Extração de texto e metadados de documentos","Reconhecimento óptico de caracteres (OCR) em imagens e documentos digitalizados","Suporte a 75+ formatos de arquivos","Vinculações nativas para várias linguagens de programação","Alto desempenho e escalabilidade"],"ru":["Извлечение текста и метаданных из документов","Оптическое распознавание символов (OCR) в изображениях и оцифрованных документах","Поддержка 75+ форматов файлов","Родные привязки для нескольких языков программирования","Высокая производительность и масштабируемость"],"ar":["استخراج النص والبيانات الوصفية من المستندات","التعرف البصري على الحروف (OCR) في الصور والوثائق الممسوحة ضوئيًا","دعم 75+ صيغة ملف","ربطات الأصلي لمختلف لغات البرمجة","أداء عالي ومتوافق"]},"keywords":{"zh":["文档智能","文档提取","Kreuzberg","Rust","Python","Node.js/TypeScript","文档分析","OCR","文档处理"],"ja":["ドキュメントインテリジェンス","ドキュメント抽出","Kreuzberg","Rust","Python","Node.js/TypeScript","ドキュメント分析","OCR","ドキュメント処理"],"ko":["문서 인텔리전스","문서 추출","Kreuzberg","Rust","Python","Node.js/TypeScript","문서 분석","OCR","문서 처리"],"es":["inteligencia de documentos","extracción de texto","reconocimiento óptico de caracteres","OCR","formatos de archivo","Rust","Python","Node.js","TypeScript"],"fr":["intelligence de documents","extraction de texte","reconnaissance optique de caractères","OCR","formats de fichiers","Rust","Python","Node.js","TypeScript"],"de":["Dokumenten-Intelligenz","Text-Extraktion","optische Zeichenerkennung","OCR","Dateiformate","Rust","Python","Node.js","TypeScript"],"pt":["Extração de documentos","Inteligência de documentos","Reconhecimento óptico de caracteres","OCR","Biblioteca de documentos","Rust","Python","Node.js","TypeScript"],"ru":["Извлечение документов","Документальная разведка","Оптическое распознавание символов","OCR","Библиотека документов","Rust","Python","Node.js","TypeScript"],"ar":["استخراج المستندات","ذكاء المستندات","التعرف البصري على الحروف","OCR","مكتبة المستندات","Rust","Python","Node.js","TypeScript"]}},"owner":"kreuzberg-dev","repo":"kreuzberg","repoPath":"kreuzberg-dev/kreuzberg","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.666Z","topics":[],"category":"community","skillMd":{"name":"kreuzberg","description":">-","version":"1.0","bodyPreview":"# Kreuzberg Document Extraction\n\nKreuzberg is a high-performance document intelligence library with a Rust core and native bindings for Python, Node.js/TypeScript, Ruby, Go, Java, C#, PHP, and Elixir. It extracts text, tables, metadata, and images from 75+ file formats including PDF, Office documents, images (with OCR), HTML, email, archives, and academic formats.\n\nUse this skill when writing code that:\n- Extracts text or metadata from documents\n- Performs OCR on scanned documents or images\n- Ba","body":"# Kreuzberg Document Extraction\n\nKreuzberg is a high-performance document intelligence library with a Rust core and native bindings for Python, Node.js/TypeScript, Ruby, Go, Java, C#, PHP, and Elixir. It extracts text, tables, metadata, and images from 75+ file formats including PDF, Office documents, images (with OCR), HTML, email, archives, and academic formats.\n\nUse this skill when writing code that:\n- Extracts text or metadata from documents\n- Performs OCR on scanned documents or images\n- Batch-processes multiple files\n- Configures extraction options (output format, chunking, OCR, language detection)\n- Implements custom plugins (post-processors, validators, OCR backends)\n\n## Installation\n\n### Python\n```bash\npip install kreuzberg\n# Optional OCR backends:\npip install kreuzberg[easyocr]    # EasyOCR\npip install kreuzberg[paddleocr]  # PaddleOCR\n```\n\n### Node.js\n```bash\nnpm install @kreuzberg/node\n```\n\n### Rust\n```toml\n# Cargo.toml\n[dependencies]\nkreuzberg = { version = \"4\", features = [\"tokio-runtime\"] }\n# features: tokio-runtime (required for sync + batch), pdf, ocr, chunking,\n#           embeddings, language-detection, keywords-yake, keywords-rake\n```\n\n### CLI\n```bash\n# Download from GitHub releases, or:\ncargo install kreuzberg-cli\n```\n\n## Quick Start\n\n### Python (Async)\n```python\nfrom kreuzberg import extract_file\n\nresult = await extract_file(\"document.pdf\")\nprint(result.content)       # extracted text\nprint(result.metadata)      # document metadata\nprint(result.tables)        # extracted tables\n```\n\n### Python (Sync)\n```python\nfrom kreuzberg import extract_file_sync\n\nresult = extract_file_sync(\"document.pdf\")\nprint(result.content)\n```\n\n### Node.js\n```typescript\nimport { extractFile } from ''@kreuzberg/node'';\n\nconst result = await extractFile(''document.pdf'');\nconsole.log(result.content);\nconsole.log(result.metadata);\nconsole.log(result.tables);\n```\n\n### Node.js (Sync)\n```typescript\nimport { extractFileSync } from ''@kreuzberg/node'';\n\nconst result = extractFileSync(''document.pdf'');\n```\n\n### Rust (Async)\n```rust\nuse kreuzberg::{extract_file, ExtractionConfig};\n\n#[tokio::main]\nasync fn main() -> kreuzberg::Result<()> {\n    let config = ExtractionConfig::default();\n    let result = extract_file(\"document.pdf\", None, &config).await?;\n    println!(\"{}\", result.content);\n    Ok(())\n}\n```\n\n### Rust (Sync) — requires `tokio-runtime` feature\n```rust\nuse kreuzberg::{extract_file_sync, ExtractionConfig};\n\nfn main() -> kreuzberg::Result<()> {\n    let config = ExtractionConfig::default();\n    let result = extract_file_sync(\"document.pdf\", None, &config)?;\n    println!(\"{}\", result.content);\n    Ok(())\n}\n```\n\n### CLI\n```bash\nkreuzberg extract document.pdf\nkreuzberg extract document.pdf --format json\nkreuzberg extract document.pdf --output-format markdown\n```\n\n## Configuration\n\nAll languages use the same configuration structure with language-appropriate naming conventions.\n\n### Python (snake_case)\n```python\nfrom kreuzberg import (\n    ExtractionConfig, OcrConfig, TesseractConfig,\n    PdfConfig, ChunkingConfig,\n)\n\nconfig = ExtractionConfig(\n    ocr=OcrConfig(\n        backend=\"tesseract\",\n        language=\"eng\",\n        tesseract_config=TesseractConfig(psm=6, enable_table_detection=True),\n    ),\n    pdf_options=PdfConfig(passwords=[\"secret123\"]),\n    chunking=ChunkingConfig(max_chars=1000, max_overlap=200),\n    output_format=\"markdown\",\n)\n\nresult = await extract_file(\"document.pdf\", config=config)\n```\n\n### Node.js (camelCase)\n```typescript\nimport { extractFile, type ExtractionConfig } from ''@kreuzberg/node'';\n\nconst config: ExtractionConfig = {\n    ocr: { backend: ''tesseract'', language: ''eng'' },\n    pdfOptions: { passwords: [''secret123''] },\n    chunking: { maxChars: 1000, maxOverlap: 200 },\n    outputFormat: ''markdown'',\n};\n\nconst result = await extractFile(''document.pdf'', null, config);\n```\n\n### Rust (snake_case)\n```rust\nuse kreuzberg::{ExtractionConfig, OcrConfig, ChunkingConfig, OutputFormat};\n\nlet config = ExtractionConfig {\n    ocr: Some(OcrConfig {\n        backend: \"tesseract\".into(),\n        language: \"eng\".into(),\n        ..Default::default()\n    }),\n    chunking: Some(ChunkingConfig {\n        max_characters: 1000,\n        overlap: 200,\n        ..Default::default()\n    }),\n    output_format: OutputFormat::Markdown,\n    ..Default::default()\n};\n\nlet result = extract_file(\"document.pdf\", None, &config).await?;\n```\n\n### Config File (TOML)\n```toml\noutput_format = \"markdown\"\n\n[ocr]\nbackend = \"tesseract\"\nlanguage = \"eng\"\n\n[chunking]\nmax_chars = 1000\nmax_overlap = 200\n\n[pdf_options]\npasswords = [\"secret123\"]\n```\n\n```bash\n# CLI: auto-discovers kreuzberg.toml in current/parent directories\nkreuzberg extract doc.pdf\n# or explicit:\nkreuzberg extract doc.pdf --config kreuzberg.toml\nkreuzberg extract doc.pdf --config-json ''{\"ocr\":{\"backend\":\"tesseract\",\"language\":\"deu\"}}''\n```\n\n## Batch Processing\n\n### Python\n```python\nfrom kreuzberg import batch_extract_files, batch_extract_files_sync\n\n# Async\nresults = await batch_extract_files([\"doc1.pdf\", \"doc2.docx\", \"doc3.xlsx\"])\n\n# Sync\nresults = batch_extract_files_sync([\"doc1.pdf\", \"doc2.docx\"])\n\nfor result in results:\n    print(f\"{len(result.content)} chars extracted\")\n```\n\n### Node.js\n```typescript\nimport { batchExtractFiles } from ''@kreuzberg/node'';\n\nconst results = await batchExtractFiles([''doc1.pdf'', ''doc2.docx'']);\n```\n\n### Rust — requires `tokio-runtime` feature\n```rust\nuse kreuzberg::{batch_extract_file, ExtractionConfig};\n\nlet config = ExtractionConfig::default();\nlet paths = vec![\"doc1.pdf\", \"doc2.docx\"];\nlet results = batch_extract_file(paths, &config).await?;\n```\n\n### CLI\n```bash\nkreuzberg batch *.pdf --format json\nkreuzberg batch docs/*.docx --output-format markdown\n```\n\n## OCR\n\nOCR runs automatically for images and scanned PDFs. Tesseract is the default backend (native binding, no external install required).\n\n### Backends\n- **Tesseract** (default): Built-in native binding. All Tesseract languages supported.\n- **EasyOCR** (Python only): `pip install kreuzberg[easyocr]`. Pass `easyocr_kwargs={\"gpu\": True}`.\n- **PaddleOCR** (Python only): `pip install kreuzberg[paddleocr]`. Pass `paddleocr_kwargs={\"use_angle_cls\": True}`.\n- **Guten** (Node.js only): Built-in OCR backend via `GutenOcrBackend`.\n\n### Language Codes\n```python\nconfig = ExtractionConfig(ocr=OcrConfig(language=\"eng\"))       # English\nconfig = ExtractionConfig(ocr=OcrConfig(language=\"eng+deu\"))   # Multiple\nconfig = ExtractionConfig(ocr=OcrConfig(language=\"all\"))       # All installed\n```\n\n### Force OCR\n```python\nconfig = ExtractionConfig(force_ocr=True)  # OCR even if text is extractable\n```\n\n## ExtractionResult Fields\n\n| Field | Python | Node.js | Rust | Description |\n|-------|--------|---------|------|-------------|\n| Text content | `result.content` | `result.content` | `result.content` | Extracted text (str/String) |\n| MIME type | `result.mime_type` | `result.mimeType` | `result.mime_type` | Input document MIME type |\n| Metadata | `result.metadata` | `result.metadata` | `result.metadata` | Document metadata (dict/object/HashMap) |\n| Tables | `result.tables` | `result.tables` | `result.tables` | Extracted tables with cells + markdown |\n| Languages | `result.detected_languages` | `result.detectedLanguages` | `result.detected_languages` | Detected languages (if enabled) |\n| Chunks | `result.chunks` | `result.chunks` | `result.chunks` | Text chunks (if chunking enabled) |\n| Images | `result.images` | `result.images` | `result.images` | Extracted images (if enabled) |\n| Elements | `result.elements` | `result.elements` | `result.elements` | Semantic elements (if element_based format) |\n| Pages | `result.pages` | `result.pages` | `result.pages` | Per-page content (if page extraction enabled) |\n| Keywords | `result.keywords` | `result.keywords` | `result.keywords` | Extracted keywords (if enabled) |\n\n## Error Handling\n\n### Python\n```python\nfrom kreuzberg import (\n    extract_file_sync, KreuzbergError, ParsingError,\n    OCRError, ValidationError, MissingDependencyError,\n)\n\ntry:\n    result = extract_file_sync(\"file.pdf\")\nexcept ParsingError as e:\n    print(f\"Failed to parse: {e}\")\nexcept OCRError as e:\n    print(f\"OCR failed: {e}\")\nexcept ValidationError as e:\n    print(f\"Invalid input: {e}\")\nexcept MissingDependencyError as e:\n    print(f\"Missing dependency: {e}\")\nexcept KreuzbergError as e:\n    print(f\"Extraction failed: {e}\")\n```\n\n### Node.js\n```typescript\nimport {\n    extractFile, KreuzbergError, ParsingError,\n    OcrError, ValidationError, MissingDependencyError,\n} from ''@kreuzberg/node'';\n\ntry {\n    const result = await extractFile(''file.pdf'');\n} catch (e) {\n    if (e instanceof ParsingError) { /* ... */ }\n    else if (e instanceof OcrError) { /* ... */ }\n    else if (e instanceof ValidationError) { /* ... */ }\n    else if (e instanceof KreuzbergError) { /* ... */ }\n}\n```\n\n### Rust\n```rust\nuse kreuzberg::{extract_file, ExtractionConfig, KreuzbergError};\n\nlet config = ExtractionConfig::default();\nmatch extract_file(\"file.pdf\", None, &config).await {\n    Ok(result) => println!(\"{}\", result.content),\n    Err(KreuzbergError::Parsing(msg)) => eprintln!(\"Parse error: {msg}\"),\n    Err(KreuzbergError::Ocr(msg)) => eprintln!(\"OCR error: {msg}\"),\n    Err(e) => eprintln!(\"Error: {e}\"),\n}\n```\n\n## Common Pitfalls\n\n1. **Python ChunkingConfig fields**: Use `max_chars` and `max_overlap`, NOT `max_characters` or `overlap`.\n2. **Rust extract_file signature**: Third argument is `&ExtractionConfig` (a reference), not `Option`. Use `&ExtractionConfig::default()` for defaults.\n3. **Rust feature gates**: `extract_file_sync`, `batch_extract_file`, and `batch_extract_file_sync` all require `features = [\"tokio-runtime\"]` in Cargo.toml.\n4. **Rust async context**: `extract_file` is async. Use `#[tokio::main]` or call from an async context.\n5. **CLI --format vs --output-format**: `--format` controls CLI output (text/json). `--output-format` controls content format (plain/markdown/djot/html).\n6. **Node.js extractFile signature**: `extractFile(path, mimeType?, config?)` — mimeType is the second arg (pass `null` to skip).\n7. **Python detect_mime_type**: The function for detecting from bytes is `detect_mime_type(data)`. For paths use `detect_mime_type_from_path(path)`.\n8. **Config file field names**: Use snake_case in TOML/YAML/JSON config files (e.g., `max_chars`, `max_overlap`, `pdf_options`).\n\n## Supported Formats (Summary)\n\n| Category | Extensions |\n|----------|-----------|\n| **PDF** | `.pdf` |\n| **Word** | `.docx`, `.odt` |\n| **Spreadsheets** | `.xlsx`, `.xlsm`, `.xlsb`, `.xls`, `.xla`, `.xlam`, `.xltm`, `.ods` |\n| **Presentations** | `.pptx`, `.ppt`, `.ppsx` |\n| **eBooks** | `.epub`, `.fb2` |\n| **Images** | `.png`, `.jpg`, `.jpeg`, `.gif`, `.webp`, `.bmp`, `.tiff`, `.tif`, `.jp2`, `.jpx`, `.jpm`, `.mj2`, `.jbig2`, `.jb2`, `.pnm`, `.pbm`, `.pgm`, `.ppm`, `.svg` |\n| **Markup** | `.html`, `.htm`, `.xhtml`, `.xml` |\n| **Data** | `.json`, `.yaml`, `.yml`, `.toml`, `.csv`, `.tsv` |\n| **Text** | `.txt`, `.md`, `.markdown`, `.djot`, `.rst`, `.org`, `.rtf` |\n| **Email** | `.eml`, `.msg` |\n| **Archives** | `.zip`, `.tar`, `.tgz`, `.gz`, `.7z` |\n| **Academic** | `.bib`, `.biblatex`, `.ris`, `.nbib`, `.enw`, `.csl`, `.tex`, `.latex`, `.typ`, `.jats`, `.ipynb`, `.docbook`, `.opml`, `.pod`, `.mdoc`, `.troff` |\n\nSee [references/supported-formats.md](references/supported-formats.md) for the complete format reference with MIME types.\n\n## Additional Resources\n\nDetailed reference files for specific topics:\n\n- **[Python API Reference](references/python-api.md)** — All functions, config classes, plugin protocols, exact signatures\n- **[Node.js API Reference](references/nodejs-api.md)** — All functions, TypeScript interfaces, worker pool APIs\n- **[Rust API Reference](references/rust-api.md)** — All functions with feature gates, structs, Cargo.toml examples\n- **[CLI Reference](references/cli-reference.md)** — All commands, flags, config precedence, exit codes\n- **[Configuration Reference](references/configuration.md)** — TOML/YAML/JSON formats, auto-discovery, env vars, full schema\n- **[Supported Formats](references/supported-formats.md)** — All 75+ formats with file extensions and MIME types\n- **[Advanced Features](references/advanced-features.md)** — Plugins, embeddings, MCP server, API server, security limits\n- **[Other Language Bindings](references/other-bindings.md)** — Go, Ruby, Java, C#, PHP, Elixir, WASM, Docker\n\nFull documentation: https://docs.kreuzberg.dev\nGitHub: https://github.com/kreuzberg-dev/kreuzberg\n"},"lastSynced":"2026-03-04T13:21:56.450Z","agentAnalysis":{"suitability":{"en":"Perfect for Document Analysis Agents needing advanced text extraction capabilities from 75+ file formats including PDF, Office documents, and images with OCR","zh":"非常适合需要从75+个文件格式（包括PDF、Office文档和带有OCR的图像）中提取高级文本的文档分析代理","ja":"75以上のファイル形式（PDF、Officeドキュメント、OCR付き画像など）から高度なテキスト抽出機能が必要なドキュメント分析エージェントに最適","ko":"75종 이상의 파일 형식(PDF, Office 문서, OCR을 지원하는 이미지 등)에서 고급 텍스트 추출 기능을 필요로 하는 문서 분석 에이전트에 적합","es":"Perfecto para Agentes de Análisis de Documentos que necesitan capacidades de extracción de texto avanzadas de más de 75 formatos de archivo, incluyendo PDF, documentos de Office y imágenes con OCR","fr":"Parfait pour les Agents d''Analyse de Documents ayant besoin de capacités de extraction de texte avancées de plus de 75 formats de fichiers, notamment PDF, documents Office et images avec OCR","de":"Perfekt für Dokumentenanalyse-Agenten, die erweiterte Textextraktionsfunktionen aus über 75 Dateiformaten benötigen, einschließlich PDF, Office-Dokumenten und Bildern mit OCR","pt":"Perfeito para Agentes de Análise de Documentos que necessitam de capacidades avançadas de extração de texto de 75+ formatos de arquivo, incluindo PDF, documentos do Office e imagens com OCR","ru":"Идеально подходит для агентов анализа документов, которым необходимы продвинутые возможности извлечения текста из 75+ форматов файлов, включая PDF, документы Office и изображения с OCR","ar":"مثالي لعميل تحليل المستندات الذين يحتاجون إلى إمكانيات متقدمة لاستخراج النص من 75+ تنسيق ملف ، بما في ذلك PDF ووثائق Office والصور مع OCR"},"recommendation":{"en":"Empowers agents to extract text, metadata, and structured information from various document formats using a high-performance Rust core, with native bindings for languages like Python, Node.js/TypeScript, and Ruby, and support for protocols like REST API and MCP server","zh":"通过高性能的Rust核心以及对Python、Node.js/TypeScript和Ruby等语言的本地绑定，并支持REST API和MCP服务器等协议，赋予代理从各种文档格式中抽取文本、元数据和结构化信息的能力","ja":"高性能のRustコアと、Python、Node.js/TypeScript、Rubyなどの言語へのネイティブバインディング、またREST APIとMCPサーバーなどのプロトコルに対するサポートにより、エージェントが様々なドキュメント形式からテキスト、メタデータ、構造化情報を抽出する能力を付与する","ko":"고성능의 Rust 코어와 Python, Node.js/TypeScript, Ruby 등 언어에 대한 네이티브 바인딩, 그리고 REST API와 MCP 서버 등을 지원하는 프로토콜을 통해 에이전트가 다양한 문서 형식에서 텍스트, 메타데이터, 구조화된 정보를 추출할 수 있는 능력을 부여","es":"Habilita a los agentes a extraer texto, metadatos e información estructurada de varios formatos de documento utilizando un núcleo de alto rendimiento en Rust, con enlaces nativos para lenguajes como Python, Node.js/TypeScript y Ruby, y soporte para protocolos como REST API y servidor MCP","fr":"Permet aux agents d''extraire du texte, des métadonnées et des informations structurées de divers formats de documents en utilisant un noyau haute performance en Rust, avec des liaisons natives pour des langages comme Python, Node.js/TypeScript et Ruby, et un support pour des protocoles comme REST API et serveur MCP","de":"Ermöglicht es Agenten, Text, Metadaten und strukturierte Informationen aus verschiedenen Dokumentformaten mithilfe eines hochleistungsfähigen Rust-Kerns zu extrahieren, mit nativen Bindungen für Sprachen wie Python, Node.js/TypeScript und Ruby und Unterstützung für Protokolle wie REST API und MCP-Server","pt":"Habilita os agentes a extrair texto, metadados e informações estruturadas de vários formatos de documento usando um núcleo de alto desempenho em Rust, com vinculações nativas para linguagens como Python, Node.js/TypeScript e Ruby, e suporte a protocolos como REST API e servidor MCP","ru":"Позволяет агентам извлекать текст, метаданные и структурированную информацию из различных форматов документов, используя ядро высокого производительности на Rust, с родными привязками для языков, таких как Python, Node.js/TypeScript и Ruby, и поддержкой протоколов, таких как REST API и сервер MCP","ar":"يسمح للعميل باستخراج النص والبيانات الوصفية والمعلومات المنظمة من تنسيقات وثائق مختلفة باستخدام نواة عالية الأداء في Rust ، مع ربط أصلي للغات مثل Python و Node.js/TypeScript و Ruby ، ودعم بروتوكولات مثل REST API و خادم MCP"},"useCases":{"en":["Extracting text and metadata from PDFs and Office documents","Performing OCR on scanned documents and images","Parsing tables and images from HTML, email, and academic formats"],"zh":["从PDF和Office文档中抽取文本和元数据","对扫描文档和图像执行OCR","从HTML、电子邮件和学术格式中解析表格和图像"],"ja":["PDFとOfficeドキュメントからテキストとメタデータを抽出する","スキャンドキュメントと画像に対してOCRを実行する","HTML、電子メール、学術形式からテーブルと画像を解析する"],"ko":["PDF와 Office 문서에서 텍스트와 메타데이터를 추출","스캔된 문서와 이미지에서 OCR을 수행","HTML, 이메일, 학술 형식에서 표와 이미지를 파싱"],"es":["Extraer texto y metadatos de PDF y documentos de Office","Realizar OCR en documentos y imágenes escaneados","Analizar tablas e imágenes de formatos HTML, correo electrónico y académicos"],"fr":["Extraire du texte et des métadonnées de PDF et de documents Office","Effectuer une reconnaissance optique de caractères (OCR) sur des documents et des images scannés","Analyser des tableaux et des images de formats HTML, courriel et universitaires"],"de":["Text und Metadaten aus PDF und Office-Dokumenten extrahieren","OCR auf gescannten Dokumenten und Bildern durchführen","Tabellen und Bilder aus HTML-, E-Mail- und akademischen Formaten parsen"],"pt":["Extrair texto e metadados de PDFs e documentos do Office","Realizar OCR em documentos digitalizados e imagens","Analise de tabelas e imagens de HTML, email e formatos acadêmicos"],"ru":["Извлечение текста и метаданных из PDF и документов Office","Выполнение OCR для сканированных документов и изображений","Парсинг таблиц и изображений из HTML, электронной почты и академических форматов"],"ar":["استخراج النص والبيانات الوصفية منPDFs ووثائق Office","إجراء OCR على المستندات الممسوحة ضوئيًا والصور","تحليل الجداول والصور من HTML والبريد الإلكتروني والتنسيقات الأكاديمية"]},"limitations":{"en":["Requires Rust core installation","Limited to supported file formats and languages"],"zh":["需要Rust核心安装","仅限支持的文件格式和语言"],"ja":["Rustコアのインストールが必要","サポート対象のファイル形式と言語に限定される"],"ko":["Rust 코어 설치가 필요","지원되는 파일 형식과 언어에만 제한"],"es":["Requiere instalación del núcleo Rust","Limitado a formatos de archivo y lenguajes compatibles"],"fr":["Nécessite l''installation du noyau Rust","Limité aux formats de fichiers et langages pris en charge"],"de":["Benötigt die Installation des Rust-Kerns","Begrenzt auf unterstützte Dateiformate und Sprachen"],"pt":["Requer instalação do núcleo Rust","Limitado aos formatos de arquivo e linguagens suportados"],"ru":["Требует установки ядра Rust","Ограничен поддерживаемыми форматами файлов и языками"],"ar":["يتطلب تثبيت النواة Rust","محدود تنسيقات الملفات واللغات المدعومة"]},"version":3},"contentHash":"4ec8fa91d9dd48bafcb32556b244d2198f6745dfadfad81fe33d33b8b3f8d316","qualityScore":50}');
